@app.route('/admin/login', methods=['GET', 'POST'])
def admin_login():
    if request.method == 'POST':
        pw = request.form.get('password', '')
        if pw == _admin_password:
            session['admin_ok'] = True
            return redirect(request.args.get('next') or '/admin')
        error_html = '<div class="err">Wrong password</div>'
        return _ADMIN_LOGIN_HTML.replace('{error}', error_html), 401
    return _ADMIN_LOGIN_HTML.replace('{error}', '')

@app.route('/admin/logout')
def admin_logout():
    session.pop('admin_ok', None)
    return redirect('/admin/login')

@app.before_request
def _check_admin_auth():
    path = request.path
    protected = (
        (path == '/admin' or path.startswith('/admin/')) and path not in ('/admin/login', '/admin/logout')
    ) or path.startswith('/api/admin/') or path.startswith('/api/system/')
    if not protected:
        return
    if session.get('admin_ok'):
        return
    if path.startswith('/api/'):
        return jsonify({'ok': False, 'error': 'Unauthorized'}), 401
    return redirect(url_for('admin_login', next=path))

# ── WEBSOCKET CLIENTS ──
ws_clients = set()
ws_lock = threading.Lock()
ws_client_ips = {}   # ip → count of active connections from that IP

_display_url = '/display'
_display_url_lock = threading.Lock()

def _navigate_home_if_needed():
    """Non-blocking: navigate kiosk to /display if on shell-game. For events with built-in delay (walkups)."""
    global _display_url
    with _display_url_lock:
        if _display_url == '/display':
            return
        broadcast('display_navigate', {'url': '/display'})
        _display_url = '/display'

def _ensure_display_for(event, data, delay=1.2):
    """Send a display event, navigating home first if not on display.html."""
    global _display_url
    # Every non-game display event (walkup, slide, standby, H2H, ...) goes
    # through here -- the one shared choke point outside the game-iframe path
    # itself. Clearing 'revealed' here means a WS-reconnect self-heal (see
    # api_state()'s live_game field and display.html's reconnect handler)
    # never resurrects a game that's since been superseded by something else,
    # even though _current_live_game itself isn't reset until the next
    # _launch_game() call.
    if _current_live_game.get('revealed'):
        _current_live_game['revealed'] = False
    with _display_url_lock:
        needs_nav = _display_url != '/display'
        if needs_nav:
            broadcast('display_navigate', {'url': '/display'})
            _display_url = '/display'
    if needs_nav:
        def _rebroadcast():
            time.sleep(delay)
            broadcast(event, data)
        threading.Thread(target=_rebroadcast, daemon=True).start()
    else:
        broadcast(event, data)

def broadcast(event, data):
    """Push state update to all connected WebSocket clients."""
    msg = json.dumps({'event': event, 'data': data})
    with ws_lock:
        clients = list(ws_clients)
    dead = set()
    for client in clients:
        try:
            client.send(msg)
        except Exception as e:
            log.debug(f"WebSocket send failed ({event}): {e}")
            dead.add(client)
    if dead:
        with ws_lock:
            ws_clients.difference_update(dead)

@sock.route('/ws')
def websocket(ws):
    remote_ip = request.remote_addr or 'unknown'
    with ws_lock:
        ws_clients.add(ws)
        ws_client_ips[remote_ip] = ws_client_ips.get(remote_ip, 0) + 1
    log.info(f"WebSocket client connected ({len(ws_clients)} total)")
    # Each connection lives at most 10 minutes, then the client auto-reconnects.
    # Every 25s we attempt a send; if it fails the connection is dead and we exit,
    # freeing the Gunicorn thread.  Without this, dead connections (browser tab
    # closed without a clean WebSocket close frame) hold threads indefinitely.
    deadline = time.time() + 600
    try:
        while time.time() < deadline:
            try:
                msg = ws.receive(timeout=25)
            except Exception:
                break
            if msg is None:
                try:
                    ws.send(json.dumps({'event': 'ping', 'data': {}}))
                except Exception:
                    break
            else:
                try:
                    incoming = json.loads(msg)
                    if incoming.get('event') == 'page_ready':
                        url = incoming.get('url', '')
                        if url:
                            global _display_url
                            with _display_url_lock:
                                _display_url = url
                            log.info(f"Display reports location: {url}")
                except Exception:
                    pass
    finally:
        with ws_lock:
            ws_clients.discard(ws)
            ws_client_ips[remote_ip] = max(0, ws_client_ips.get(remote_ip, 1) - 1)
            if ws_client_ips[remote_ip] == 0:
                ws_client_ips.pop(remote_ip, None)
        log.info(f"WebSocket client disconnected ({len(ws_clients)} remaining)")

# ── AUDIO ENGINE ──
def _init_mixer(retries=5, delay=2):
    for attempt in range(1, retries + 1):
        try:
            pygame.mixer.init(frequency=44100, size=-16, channels=2, buffer=4096)
            pygame.mixer.set_num_channels(8)
            log.info("pygame mixer initialised")
            return
        except Exception as e:
            log.warning(f"pygame mixer init attempt {attempt}/{retries} failed: {e}")
            if attempt < retries:
                time.sleep(delay)
    log.error("pygame mixer could not initialise — audio will be unavailable")

