# ── CROWD LIGHTING HELPERS ─────────────────────────────────────────────────────
def _hex_to_rgb(h):
    h = h.lstrip('#')
    return [int(h[i:i+2], 16) for i in (0, 2, 4)]

def _lerp(a, b, t):
    return int(a + (b - a) * t)

def _crowd_color_rgb(cfg, lv):
    """Interpolate low→mid→high crowd colors (from config or defaults)."""
    lo = _hex_to_rgb(cfg.get('crowd_color_low',  '#FF6400'))
    mi = _hex_to_rgb(cfg.get('crowd_color_mid',  '#FFB400'))
    hi = _hex_to_rgb(cfg.get('crowd_color_high', '#FFE050'))
    if lv <= 0.5:
        t = lv * 2
        return [_lerp(lo[i], mi[i], t) for i in range(3)]
    else:
        t = (lv - 0.5) * 2
        return [_lerp(mi[i], hi[i], t) for i in range(3)]

def _dmx_crowd_channels(fix, lv, color):
    """Raw DMX channel values for continuous crowd-level tracking on a pole fixture.
    Assumes the two documented pole fixture layouts (see project_pole_dmx memory):
    6ch pinspot has no dedicated dimmer — CH1 must stay 255 (unlock RGBW) and CH6
    stays 0 (manual), so brightness is achieved by scaling the RGB channels directly.
    8ch wash has a real CH1 master dimmer, so RGB stays at full color and CH1 carries
    the level; CH6/CH7 stay 0 (no strobe, manual mode)."""
    n = fix.get('channels', 6)
    r, g, b = color
    if n <= 6:
        return ([255, int(r * lv), int(g * lv), int(b * lv), 0, 0])[:n]
    else:
        return ([int(255 * lv), r, g, b, 0, 0, 0, 0])[:n]

_wled_last_preset: dict = {}   # ip → last preset number fired

def _wled_post(ip, payload):
    try:
        requests.post(f'http://{_resolve_ip_once(ip)}/json/state', json=payload, timeout=0.4)
    except Exception:
        _invalidate_ip(ip)

def _wled_fire_preset(ip, preset_num):
    """Fire a WLED preset by number and remember it for segment restore.
    Sends twice with a short gap to survive concurrent crowd animation traffic."""
    _wled_last_preset[ip] = preset_num
    resolved = _resolve_ip_once(ip)
    try:
        requests.post(f'http://{resolved}/json', json={'ps': preset_num}, timeout=0.5)
    except Exception:
        _invalidate_ip(ip)
    time.sleep(0.08)
    try:
        requests.post(f'http://{resolved}/json', json={'ps': preset_num}, timeout=0.5)
    except Exception:
        _invalidate_ip(ip)

def _fetch_wled_led_count(ip):
    """Return total LED count from WLED /json/info, or None on failure."""
    try:
        r = requests.get(f'http://{_resolve_ip_once(ip)}/json/info', timeout=3)
        return r.json().get('leds', {}).get('count')
    except Exception:
        _invalidate_ip(ip)
        return None

def _countdown_led_devices(countdown_cfg):
    """Return WLED device dicts with total_leds+strips_per_pole set, filtered by countdown_cfg."""
    cfg = load_config()
    ids = countdown_cfg.get('countdown_led_devices') or []
    devs = [d for d in cfg.get('wled_devices', [])
            if (not ids or d.get('id') in ids)
            and d.get('ip') and d.get('total_leds') and d.get('strips_per_pole')]
    return devs

def _update_countdown_leds(remaining, warning_secs, countdown_cfg):
    """Push a two-segment yellow→red fill to each configured WLED device."""
    if warning_secs <= 0:
        return
    fraction = max(0.0, min(1.0, remaining / warning_secs))
    r_val, g_val = 255, int(255 * fraction)
    for dev in _countdown_led_devices(countdown_cfg):
        ip           = dev['ip'].strip()
        total_leds   = int(dev['total_leds'])
        strips       = int(dev['strips_per_pole'])
        leds_per_strip = total_leds // strips
        n_lit = round(leds_per_strip * fraction)
        segs = []
        for i in range(strips):
            base   = i * leds_per_strip
            seg_id = i * 2
            if n_lit > 0:
                segs.append({'id': seg_id, 'start': base, 'stop': base + n_lit,
                             'col': [[r_val, g_val, 0]], 'fx': 0, 'on': True})
            segs.append({'id': seg_id + 1, 'start': base + n_lit,
                         'stop': base + leds_per_strip,
                         'col': [[0, 0, 0]], 'fx': 0, 'on': True})
        threading.Thread(target=_wled_post, args=(ip, {'seg': segs}), daemon=True).start()

def _clear_countdown_leds(countdown_cfg):
    """Restore WLED segment layout after countdown by re-firing the last known preset.
    Falls back to brightness-off if no preset has been fired on that device."""
    for dev in _countdown_led_devices(countdown_cfg):
        ip = dev['ip'].strip()
        last = _wled_last_preset.get(ip)
        if last is not None:
            threading.Thread(target=_wled_fire_preset, args=(ip, last), daemon=True).start()
        else:
            threading.Thread(target=_wled_post, args=(ip, {'bri': 0}), daemon=True).start()

_crowd_led_display = 0.0   # current animated VU fill level (0–1), driven by anim thread

def _fire_crowd_strip_leds(fraction, cfg):
    """Push a VU-meter fill to crowd_lights via WLED UDP realtime (DRGB protocol).
    Sends raw per-LED colors — no segment management, no HTTP overhead, no drops."""
    light_ids  = cfg.get('crowd_lights', [])
    if not light_ids:
        return
    strip_len  = max(1, int(cfg.get('crowd_strip_len', 60)))
    num_strips = max(1, int(cfg.get('crowd_num_strips', 1)))
    nodes_map  = {n['id']: n.get('ip') for n in cfg.get('pole_nodes',   []) if n.get('ip')}
    wled_map   = {d['id']: d.get('ip') for d in cfg.get('wled_devices', []) if d.get('ip')}
    ip_map     = {**nodes_map, **wled_map}

    r, g, b = [int(round(c)) for c in _crowd_color_rgb(cfg, fraction)]
    n_lit   = round(strip_len * fraction)

    # Build pixel array: n_lit LEDs per strip lit, rest black
    total  = num_strips * strip_len
    pixels = bytearray(total * 3)   # initialized to all zeros (black)
    for i in range(num_strips):
        base = i * strip_len
        for j in range(n_lit):
            idx = (base + j) * 3
            pixels[idx]     = r
            pixels[idx + 1] = g
            pixels[idx + 2] = b

    # WLED DRGB realtime protocol: [0x02, timeout×100ms, R0,G0,B0, R1,G1,B1, ...]
    packet = bytes([0x02, 20]) + bytes(pixels)   # 20 × 100ms = 2s revert timeout

    for lid in light_ids:
        ip = ip_map.get(lid)
        if ip:
            try:
                # UDP sendto() resolves a hostname just like requests.post()
                # would — this loop runs at 8Hz whenever crowd_climb_mode is
                # on, so an unresolved hostname here would mean this thread
                # blocks on mDNS up to 8x/sec instead of once.
                _wled_udp_sock.sendto(packet, (_resolve_ip_once(ip), 19446))
            except Exception:
                _invalidate_ip(ip)

def _dmx_post(ip, fixtures):
    try:
        requests.post(f'http://{_resolve_ip_once(ip)}/dmx', json={'fixtures': fixtures}, timeout=0.4)
    except Exception:
        _invalidate_ip(ip)

def _build_dim_mask(fix, fixture_types):
    """True per channel = dimmable (no presets). False = control channel (MODE, EFFECT…)."""
    type_def = fixture_types.get(fix.get('type', ''), {})
    ch_defs  = type_def.get('ch_defs', [])
    mask = [not bool(ch.get('presets')) for ch in ch_defs]
    ch_count = fix.get('channels', len(mask))
    while len(mask) < ch_count:
        mask.append(True)
    return mask[:ch_count]

def _dim_channels(channels, dim, mask=None):
    """Scale only dimmable channels; leave control channels at their raw value."""
    if mask is None:
        mask = [True] * len(channels)
    return [int(v * dim) if mask[i] else int(v) for i, v in enumerate(channels)]

def _walkup_color_anim(preset_num, color1_hex, color2_hex, cancel_event, cfg):
    """Fire crowd-light animation for a circle walkup. Sends ONE command and holds.
    If preset_num is set, fires that WLED preset (user-configured in WLED UI).
    Otherwise falls back to Theater Chase built-in effect using the circle's colours."""
    global _walkup_led_active
    _walkup_led_active = True
    try:
        nodes_map = {n['id']: n.get('ip') for n in cfg.get('pole_nodes',   []) if n.get('ip')}
        wled_map  = {d['id']: d.get('ip') for d in cfg.get('wled_devices', []) if d.get('ip')}
        ip_map    = {**nodes_map, **wled_map}
        light_ids = cfg.get('crowd_lights', [])
        if not light_ids:
            return

        seen_ips = set()
        for lid in light_ids:
            ip = ip_map.get(lid)
            if not ip or ip in seen_ips:
                continue
            seen_ips.add(ip)
            if preset_num is not None:
                _wled_fire_preset(ip, preset_num)
            else:
                # Theater Chase — read full segment state first, patch only the
                # effect fields, then send the whole payload back. This matches
                # what a WLED preset recall does (full atomic state write) and
                # avoids partial-update quirks in WLED 0.15.x that drop seg 4.
                strip_len  = max(1, int(cfg.get('crowd_strip_len', 60)))
                num_strips = max(1, int(cfg.get('crowd_num_strips', 1)))
                c1 = [int(round(x)) for x in _hex_to_rgb(color1_hex or '#FF0000')]
                c2 = [int(round(x)) for x in _hex_to_rgb(color2_hex or '#0000FF')]
                try:
                    state = requests.get(f'http://{_resolve_ip_once(ip)}/json/state', timeout=1.5).json()
                    existing = {s['id']: s for s in state.get('seg', [])}
                except Exception:
                    _invalidate_ip(ip)
                    existing = {}
                segments = []
                for i in range(num_strips):
                    # Carry over structural WLED fields so this is a full state
                    # write (avoids WLED 0.15.x partial-update quirks), but always
                    # use MusicMan's configured boundaries — never a stray preset's.
                    seg = dict(existing.get(i, {}))
                    seg.update({'id': i,
                                'start': i * strip_len, 'stop': (i + 1) * strip_len,
                                'col': [c1, c2, [0, 0, 0]], 'fx': 15, 'sx': 80,
                                'on': True, 'bri': 255, 'of': 0})
                    segments.append(seg)
                # Pass through segments beyond our range so WLED sees a full write
                for sid, seg in existing.items():
                    if sid >= num_strips:
                        segments.append(seg)
                _wled_post(ip, {'seg': segments})

        cancel_event.wait()
    finally:
        _walkup_led_active = False


def _send_crowd_lights(level, climax):
    """Fire-and-forget WLED + DMX updates for crowd lighting. Runs in a daemon thread."""
    global _crowd_post_climax
    cfg          = load_config()
    light_ids    = cfg.get('crowd_lights', [])
    # None = DMX crowd tracking never configured (opt-in required, no surprise
    # behavior on existing installs); [] = explicitly "track no fixtures";
    # [...] = these specific fixtures. Only a real list (any length) turns it on.
    dmx_selected     = cfg.get('crowd_dmx_fixtures')
    has_dmx_fixtures = dmx_selected is not None and any(node.get('fixtures') for node in cfg.get('pole_nodes', []))
    if not light_ids and not has_dmx_fixtures and not (climax and cfg.get('crowd_climax_macro_id')):
        return
    if _crowd_post_climax and not climax:
        return  # post-climax lockout: revert scene owns the lights until operator re-engages

    nodes_map = {n['id']: n.get('ip') for n in cfg.get('pole_nodes',   []) if n.get('ip')}
    wled_map  = {d['id']: d.get('ip') for d in cfg.get('wled_devices', []) if d.get('ip')}
    ip_map    = {**nodes_map, **wled_map}

    lv         = level / 100.0
    climb_mode = cfg.get('crowd_climb_mode', False)
    strip_len  = max(1, int(cfg.get('crowd_strip_len', 80)))

    # ── WLED payload ──────────────────────────────────────────────────────────
    # climb_mode LED updates are handled by the 30Hz animation thread; only fire here for
    # climax (strobe burst) or non-climb brightness mode.
    if climax:
        num_strips = max(1, int(cfg.get('crowd_num_strips', 1)))
        wled_payload = {'bri': 255, 'seg': [
            {'id': i, 'start': i * strip_len, 'stop': (i + 1) * strip_len,
             'fx': 11, 'sx': 220, 'ix': 255,
             'col': [[255, 255, 255], [0, 0, 0], [0, 0, 0]], 'on': True}
            for i in range(num_strips)
        ]}
        for lid in light_ids:
            ip = ip_map.get(lid)
            if ip:
                threading.Thread(target=_wled_post, args=(ip, wled_payload), daemon=True).start()
    elif not climb_mode:
        col = _crowd_color_rgb(cfg, lv)
        bri = max(8, int(lv * 255))
        num_strips = max(1, int(cfg.get('crowd_num_strips', 1)))
        wled_payload = {'bri': bri, 'seg': [
            {'id': i, 'start': i * strip_len, 'stop': (i + 1) * strip_len,
             'fx': 0, 'ix': int(lv * 255),
             'col': [col, [0, 0, 0], [0, 0, 0]], 'on': True}
            for i in range(num_strips)
        ]}
        for lid in light_ids:
            ip = ip_map.get(lid)
            if ip:
                threading.Thread(target=_wled_post, args=(ip, wled_payload), daemon=True).start()

    # ── DMX fixture tracking (dim/color follow crowd level) ──────────────────
    # Runs alongside WLED, independent of climb_mode — pole fixtures always
    # track brightness+color directly, no VU-meter-style climb for DMX.
    if not climax and has_dmx_fixtures:
        col = _crowd_color_rgb(cfg, lv)
        for node in cfg.get('pole_nodes', []):
            if not node.get('ip'):
                continue
            fixtures_out = []
            for fix in node.get('fixtures', []):
                key = f"{node['id']}::{fix.get('id')}"
                if key not in dmx_selected:
                    continue
                fixtures_out.append({'start': fix.get('start', 1),
                                      'channels': _dmx_crowd_channels(fix, lv, col)})
            if fixtures_out:
                threading.Thread(target=_dmx_post, args=(node['ip'], fixtures_out), daemon=True).start()

    # ── Climax: fire the assigned macro, then revert to a scene afterward ────
    # Climax behavior (scenes, SFX, video, whatever) lives in the macro itself —
    # build a "Climax" macro with the steps you want instead of configuring it here.
    if climax:
        global _crowd_led_display
        _crowd_post_climax = True   # guard before macro fires so viz_hide/display events can't race
        _crowd_led_display = 0.0   # zero before anim pauses so it starts from 0 when it resumes
        _stop_music()   # stops music + playlist, but leaves SFX channel so explosion SFX can play
        climax_dur = cfg.get('crowd_climax_duration_ms', 2500) / 1000.0
        macro_id   = cfg.get('crowd_climax_macro_id', '')
        revert_id  = cfg.get('crowd_revert_macro_id', '')
        all_macros = {m['id']: m for m in cfg.get('macros', [])}
        if macro_id:
            macro = all_macros.get(macro_id)
            if macro:
                # Pre-warm SFX cache so Sound() file I/O doesn't delay the first play
                sfx_dir = ASSETS_DIR / 'sfx'
                for step in macro.get('steps', []):
                    if step.get('action') == 'sfx':
                        name = step.get('name', '')
                        for ext in ('.mp3', '.wav', '.ogg', '.flac'):
                            fp = sfx_dir / (name + ext)
                            if fp.exists():
                                if str(fp) not in _sfx_cache:
                                    try:
                                        _sfx_cache[str(fp)] = pygame.mixer.Sound(str(fp))
                                    except Exception:
                                        pass
                                break
                # Fire every climax step simultaneously — no sequential waits, instant impact.
                cancel = threading.Event()
                for step in macro.get('steps', []):
                    if step.get('action') == 'wait':
                        continue
                    single = {**macro, 'steps': [step]}
                    threading.Thread(target=execute_macro, args=(single, cancel), daemon=True).start()

        def _after_climax(dur=climax_dur, rsid=revert_id, macro_map=all_macros):
            global _crowd_post_climax
            time.sleep(dur)
            _crowd_post_climax = True   # set BEFORE revert macro so viz_hide/display_step can't race
            if rsid:
                revert_macro = macro_map.get(rsid)
                if revert_macro:
                    execute_macro(revert_macro)
            _crowd_state['climax']  = False
            _crowd_state['level']   = 0
            broadcast('viz_crowd', _crowd_state)

        threading.Thread(target=_after_climax, daemon=True).start()

# ── SOUND LEVEL POLLING ───────────────────────────────────────────────────────
_sound_levels    = {}    # node_id → {'level': 0-100, 'name': str, 'ip': str}
_sound_poll_on   = False
_crowd_anim_running = False  # separate flag so crowd LED anim can be stopped independently
_sound_ema       = {}    # node_id → smoothed float (0-100); EMA across poll cycles
_SOUND_EMA_ALPHA = 0.15  # ~13 s time constant at 2 s poll interval

# ── PLAYLIST ENGINE ──
AUDIO_EXTS = {'.mp3', '.flac', '.ogg', '.wav', '.m4a', '.aac', '.opus'}

playlist_state = {
    'active':     False,
    'path':       '',
    'index':      0,
    'total':      0,
    'shuffle':    False,
    'track_name': '',
}
_playlist_tracks     = []
_playlist_advance_id = 0

_usb_mount_cache  = (None, 0.0)  # (result, timestamp)
_USB_MOUNT_TTL    = 5.0

def _find_usb_mount_raw():
    """Scan for USB mount with no caching."""
    import re, os
    try:
        with open('/proc/mounts') as mf:
            for line in mf:
                parts = line.split()
                if len(parts) < 2:
                    continue
                dev, mount_raw = parts[0], parts[1]
                if not re.match(r'/dev/sd[a-z]\d+$', dev):
                    continue
                if not Path(dev).exists():
                    continue
                mount = Path(mount_raw.replace('\\040', ' '))
                if mount.is_dir() and os.path.ismount(str(mount)):
                    try:
                        next(mount.iterdir())
                        return str(mount)
                    except StopIteration:
                        pass
    except OSError:
        pass
    for path in ['/media/usbstick', '/media/usb0', '/media/usb1', '/media/usb2', '/media/usb3', '/media/usb']:
        if os.path.ismount(path):
            try:
                next(Path(path).iterdir())
                return path
            except (StopIteration, FileNotFoundError):
                pass
    try:
        for child in sorted(Path('/media/pi').iterdir()):
            if child.is_dir() and os.path.ismount(str(child)):
                try:
                    next(child.iterdir())
                    return str(child)
                except StopIteration:
                    pass
    except FileNotFoundError:
        pass
    return None

def _find_usb_mount():
    """Return first mounted, non-empty USB storage partition, or None. Cached 5s."""
    global _usb_mount_cache
    result, ts = _usb_mount_cache
    if time.monotonic() - ts < _USB_MOUNT_TTL:
        return result
    result = _find_usb_mount_raw()
    _usb_mount_cache = (result, time.monotonic())
    return result

def scan_playlist(path):
    p = Path(path)
    if p.suffix.lower() == '.m3u':
        tracks = []
        try:
            with open(p, encoding='utf-8', errors='ignore') as f:
                for line in f:
                    line = line.strip()
                    if line and not line.startswith('#'):
                        tp = Path(line) if Path(line).is_absolute() else p.parent / line
                        if tp.exists():
                            tracks.append(str(tp))
        except Exception as e:
            log.error(f'M3U parse error: {e}')
        return tracks
    elif p.is_dir():
        return sorted(str(f) for f in p.rglob('*') if f.suffix.lower() in AUDIO_EXTS and f.is_file())
    elif p.suffix.lower() in AUDIO_EXTS and p.is_file():
        return [str(p)]  # single track — a "playlist" of one, so USB search results can reuse play_playlist()
    return []

def _advance_playlist_to(idx):
    global _playlist_advance_id
    _playlist_advance_id += 1
    my_id = _playlist_advance_id
    if idx >= len(_playlist_tracks):
        playlist_state['active']     = False
        playlist_state['track_name'] = ''
        broadcast('playlist_state', playlist_state)
        return
    playlist_state['index']      = idx
    playlist_state['track_name'] = Path(_playlist_tracks[idx]).stem
    play_audio(_playlist_tracks[idx])
    my_session = _audio_session   # capture after play_audio increments it
    broadcast('playlist_state', playlist_state)
    def _watch():
        while True:
            time.sleep(1)
            if _playlist_advance_id != my_id or not playlist_state.get('active'):
                return
            if _audio_session != my_session:
                # A walkup or macro replaced the audio — stop trying to advance
                return
            if not pygame.mixer.music.get_busy() and not audio_state.get('paused'):
                _advance_playlist_to(idx + 1)
                return
    threading.Thread(target=_watch, daemon=True).start()

def play_playlist(path, shuffle=False):
    global _playlist_tracks
    tracks = scan_playlist(path)
    if not tracks:
        log.warning(f'Playlist: no audio found at {path}')
        return
    if shuffle:
        import random
        random.shuffle(tracks)
    _playlist_tracks = tracks
    playlist_state.update({
        'active':     True,
        'path':       path,
        'index':      0,
        'total':      len(tracks),
        'shuffle':    shuffle,
        'track_name': Path(tracks[0]).stem,
    })
    broadcast('playlist_state', playlist_state)
    _advance_playlist_to(0)

def _file_duration(path):
    """Return audio file length in seconds, or 0 if unknown."""
    try:
        ext = Path(path).suffix.lower()
        if ext == '.mp3':
            return round(MutagenMP3(str(path)).info.length, 2)
        if ext in ('.wav', '.wave'):
            return round(MutagenWAV(str(path)).info.length, 2)
    except Exception:
        pass
    return 0

def play_audio(filepath, volume=None, start_pos=0, loops=0, crossfade_ms=3000, on_loaded=None):
    """Play an audio file, fading out any currently playing track first.
    on_loaded() is called immediately after the file is loaded, before play() —
    use it to fire display changes so sound and video start at the same moment."""
    global _audio_session
    _audio_session += 1
    try:
        if not os.path.exists(filepath):
            log.error(f"Audio file not found: {filepath}")
            return False
        if crossfade_ms > 0 and pygame.mixer.music.get_busy():
            orig = pygame.mixer.music.get_volume()
            steps = max(10, int(crossfade_ms / 1000 * 20))
            interval = crossfade_ms / 1000 / steps
            for i in range(steps - 1, -1, -1):
                if not pygame.mixer.music.get_busy():
                    break
                pygame.mixer.music.set_volume(orig * i / steps)
                time.sleep(interval)
        pygame.mixer.music.stop()
        pygame.mixer.music.load(filepath)
        if on_loaded:
            try:
                on_loaded()
            except Exception as e:
                log.warning(f"play_audio on_loaded error: {e}")
        try:
            ext = Path(filepath).suffix.lower()
            if ext == '.mp3':
                audio_state['duration'] = round(MutagenMP3(filepath).info.length, 2)
            elif ext in ('.wav', '.wave'):
                audio_state['duration'] = round(MutagenWAV(filepath).info.length, 2)
            else:
                audio_state['duration'] = 0
        except Exception:
            audio_state['duration'] = 0
        vol = (volume or audio_state['volume']) / 100
        pygame.mixer.music.set_volume(vol)
        pygame.mixer.music.play(loops=loops, start=start_pos)
        audio_state['playing'] = True
        audio_state['paused'] = False
        audio_state['current_track']      = os.path.basename(filepath)
        audio_state['current_track_path'] = str(filepath)
        broadcast('audio_state', audio_state)
        log.info(f"Playing: {filepath}")
        return True
    except Exception as e:
        log.error(f"Audio play error: {e}")
        return False

def play_sfx(filepath, volume=None, fade_ms=0):
    """Play a sound effect on a separate channel (doesn't stop music)."""
    global _sfx_channel
    try:
        if filepath not in _sfx_cache:
            if len(_sfx_cache) >= _SFX_CACHE_MAX:
                for k in list(_sfx_cache):
                    if not _sfx_cache[k].get_num_channels():
                        _sfx_cache.pop(k)
                        break
                else:
                    _sfx_cache.pop(next(iter(_sfx_cache)))
            _sfx_cache[filepath] = pygame.mixer.Sound(filepath)
        sound = _sfx_cache[filepath]
        vol = (volume or sfx_state['volume']) / 100
        sound.set_volume(vol)
        channel = sound.play(fade_ms=int(fade_ms))
        _sfx_channel = channel
        sfx_name = Path(filepath).stem
        duration = round(sound.get_length(), 2)
        sfx_state['playing']  = True
        sfx_state['paused']   = False
        sfx_state['name']     = sfx_name
        sfx_state['duration'] = duration
        broadcast('sfx_state', sfx_state)
        log.info(f"SFX: {filepath}")
        deadline = time.time() + duration + 5
        def _sfx_done(name=sfx_name, ch=channel):
            while ch and ch.get_busy() and time.time() < deadline:
                time.sleep(0.05)
            if sfx_state.get('name') == name and sfx_state.get('playing'):
                sfx_state['playing'] = False
                sfx_state['paused']  = False
                broadcast('sfx_state', sfx_state)
        threading.Thread(target=_sfx_done, daemon=True).start()
    except Exception as e:
        log.error(f"SFX error: {e}")

def fade_audio(duration=None):
    """Fade out currently playing audio (music + active SFX channel)."""
    global _playlist_advance_id
    dur_sec = float(duration or config['audio']['fade_duration'])
    _playlist_advance_id += 1
    playlist_state['active']     = False
    playlist_state['track_name'] = ''
    broadcast('playlist_state', playlist_state)
    my_advance_id = _playlist_advance_id

    def _do_fade():
        # Manual volume ramp — more reliable than pygame fadeout() on SDL/Pi
        if pygame.mixer.music.get_busy():
            orig = pygame.mixer.music.get_volume()
            steps = max(10, int(dur_sec * 20))
            interval = dur_sec / steps
            for i in range(steps - 1, -1, -1):
                if _playlist_advance_id != my_advance_id:
                    # A new fade or play_audio took over — stop meddling
                    return
                if not pygame.mixer.music.get_busy():
                    break
                pygame.mixer.music.set_volume(orig * i / steps)
                time.sleep(interval)
            pygame.mixer.music.stop()
            pygame.mixer.music.set_volume(orig)
        if _sfx_channel and sfx_state.get('playing'):
            _sfx_channel.fadeout(int(dur_sec * 1000))
        audio_state['playing'] = False
        audio_state['paused']  = False
        broadcast('audio_state', audio_state)

    threading.Thread(target=_do_fade, daemon=True).start()

def _stop_music():
    """Stop music/playlist without touching the SFX channel."""
    global _playlist_advance_id
    _playlist_advance_id += 1
    playlist_state['active']     = False
    playlist_state['track_name'] = ''
    pygame.mixer.music.stop()
    audio_state['playing'] = False
    audio_state['paused']  = False
    audio_state['current_track'] = None
    broadcast('audio_state', audio_state)

def stop_audio():
    """Immediately stop all audio including SFX."""
    global _sfx_channel
    _stop_music()
    pygame.mixer.stop()
    _sfx_channel = None
    sfx_state['playing'] = False
    sfx_state['paused']  = False
    broadcast('sfx_state', sfx_state)
    broadcast('playlist_state', playlist_state)

def set_volume(v):
    """Set music volume 0-100."""
    audio_state['volume'] = int(v)
    pygame.mixer.music.set_volume(int(v) / 100)
    broadcast('audio_state', audio_state)

def set_sfx_volume(v):
    """Set SFX volume 0-100."""
    sfx_state['volume'] = int(v)
    broadcast('sfx_state', sfx_state)

# ── SKIT TIMER ──
def _timer_state_from_cfg(cfg):
    t = cfg.get('timer', {})
    return {
        'running': False,
        'paused':  False,
        'seconds_remaining': t.get('duration', 180),
        'duration':          t.get('duration', 180),
        'warning_fired': False,
        'expired': False,
        'visible_on_display': False,   # currently showing on HDMI right now -- distinct
                                        # from show_on_display, which is the persistent
                                        # admin toggle for whether it's allowed to show at all
        'preset_name':        t.get('active_preset', ''),
        'show_on_display':    t.get('show_on_display', False),
        'show_end_display':   t.get('show_end_display', True),
        'warning_at':         t.get('warning_at', 15),
        'start_sound':        t.get('start_sound', ''),
        'start_sound_start':  t.get('start_sound_start', 0),
        'start_sound_duration': t.get('start_sound_duration', 0),
        'start_sound_fade':   t.get('start_sound_fade', 0),
        'start_sound_loop':   t.get('start_sound_loop', True),
        'warning_sound':      t.get('warning_sound', ''),
        'warning_scene':      t.get('warning_scene', ''),
        'end_sound':          t.get('end_sound', ''),
        'end_scene':          t.get('end_scene', ''),
    }

timer_state = _timer_state_from_cfg(config)
timer_thread = None
timer_stop_event = threading.Event()

stopwatch_state = {
    'running': False,
    'start_ms': None,
    'elapsed_ms': 0,
    'show_on_display': False,
}

# Persisted "what's currently happening" — unlike the show_step WS broadcast
# (a fire-and-forget event, missed entirely by any client that wasn't
# connected at that instant), this is queryable at any time via
# /api/remote/state. Built for the M5Stick remote, which walks around
# outdoors and will routinely reconnect mid-show — on reconnect it needs to
# ask "what's current?" directly rather than wait for the next event.
_current_show_step = {
    'index': None, 'type': None, 'name': '', 'desc': '',
    'game_type_id': '', 'game_config_id': '', 'controller_url': '', 'display_url': '',
}
_current_show_step_lock = threading.Lock()

def _set_current_show_step(**kwargs):
    global _current_show_step
    step = {
        'index': None, 'type': None, 'name': '', 'desc': '',
        'game_type_id': '', 'game_config_id': '', 'controller_url': '', 'display_url': '',
        'has_timer': False,
    }
    step.update(kwargs)
    with _current_show_step_lock:
        _current_show_step = step

# M5Stick remote connection status — surfaced in Console/Admin the same way
# pole nodes and battery units are (see /api/health). Originally tracked via
# a persistent WebSocket connection (a 'remote_hello' identify message on
# connect, cleared on disconnect) — dropped that after finding a one-sided
# failure in the field: the ESP32's WebSocketsClient believed the connection
# stayed up (isConnected()==true for 20+s straight in its own serial log)
# while flask-sock silently closed it server-side within seconds every time,
# for reasons that didn't repro cleanly. Plain HTTP proved completely
# reliable across dozens of consecutive calls on the same link, so
# 'connected' is now heartbeat-based instead: the remote POSTs
# /api/remote/heartbeat periodically, and a background thread marks it
# disconnected if too long passes without one — same staleness pattern
# already used for pole-node/battery reachability elsewhere in this file.
_remote_status = {'connected': False, 'last_seen': None, 'battery_pct': None, 'ip': None}
_remote_status_lock = threading.Lock()
_REMOTE_HEARTBEAT_STALE_S = 15   # heartbeat every ~5s expected; 3 misses = disconnected

def _set_remote_status(**kwargs):
    global _remote_status
    with _remote_status_lock:
        _remote_status = {**_remote_status, **kwargs}
        snapshot = dict(_remote_status)
    broadcast('remote_status', snapshot)

def _start_remote_staleness_check():
    def _loop():
        while True:
            time.sleep(5)
            with _remote_status_lock:
                last_seen = _remote_status.get('last_seen')
                was_connected = _remote_status.get('connected')
            if was_connected and last_seen and (time.time() - last_seen > _REMOTE_HEARTBEAT_STALE_S):
                _set_remote_status(connected=False)
                log.info("M5 remote heartbeat stale — marking disconnected")
    threading.Thread(target=_loop, daemon=True, name='remote-staleness').start()

# Games-tab countdown — fully independent from the skit timer
countdown_state = {
    'running': False,
    'paused':  False,
    'seconds_remaining': 180,
    'duration': 180,
    'expired':  False,
    'show_on_display': False,
    'show_end_display': True,
    'start_sound': '',
    'start_sound_duration': 0.0,
    'start_sound_fade': 3.0,
    'start_sound_loop': True,
    'end_sound': '',
    'end_display': '',
    'countdown_leds': False,
}
countdown_thread     = None
countdown_stop_event = threading.Event()
_cd_sound_stop          = threading.Event()
_cd_sound_looping       = False  # True only while a looping countdown sound is active
_cd_sound_paused        = threading.Event()  # set while countdown sound is pause-held
_cd_pre_end_slide       = {}     # display state saved just before the end display fires
_timer_sound_stop       = threading.Event()
_timer_sound_looping    = False  # True only while a looping skit timer sound is active
_timer_sound_paused     = threading.Event()  # set while skit timer sound is pause-held
_timer_pre_end_slide    = {}     # display state saved just before the end display fires

def timer_worker():
    global timer_state
    while not timer_stop_event.is_set():
        time.sleep(1)
        if not timer_state['running']:
            continue
        timer_state['seconds_remaining'] -= 1
        broadcast('timer_state', timer_state)
        # Warning
        tcfg = config.get('timer', {})
        # LED strip countdown fill — runs every tick inside the warning window
        if (tcfg.get('countdown_leds')
                and 0 < timer_state['seconds_remaining'] <= tcfg.get('warning_at', 15)):
            threading.Thread(target=_update_countdown_leds,
                             args=(timer_state['seconds_remaining'],
                                   tcfg.get('warning_at', 15), tcfg),
                             daemon=True).start()
        if timer_state['seconds_remaining'] <= tcfg.get('warning_at', 15) \
                and not timer_state['warning_fired']:
            timer_state['warning_fired'] = True
            sfx_name = tcfg.get('warning_sound', '')
            if sfx_name:
                sfx_path = _resolve_audio_file(sfx_name)
                if sfx_path:
                    play_sfx(str(sfx_path))
            warn_scene = tcfg.get('warning_scene', '')
            if warn_scene:
                wled_set_scene(warn_scene)
            disp_file = tcfg.get('warning_display', '')
            if disp_file:
                _broadcast_timer_display(disp_file)
            timer_state['visible_on_display'] = True
            broadcast('timer_warning', {'seconds_remaining': timer_state['seconds_remaining'],
                                        'warning_fired': True, 'running': True})
            log.info("Timer: warning fired")
        # Expired
        if timer_state['seconds_remaining'] <= 0:
            timer_state['seconds_remaining'] = 0
            timer_state['running'] = False
            timer_state['expired'] = True
            tcfg = config.get('timer', {})
            # If start sound is still playing, fade it out before the end sound
            if _timer_sound_looping:
                _timer_sound_stop.set()
                time.sleep(0.1)  # let the sound thread exit its loop
                fade_sec = float(timer_state.get('start_sound_fade', 3))
                if fade_sec > 0:
                    vol = pygame.mixer.music.get_volume()
                    steps = max(10, int(fade_sec * 20))
                    interval = fade_sec / steps
                    for i in range(steps - 1, -1, -1):
                        pygame.mixer.music.set_volume(vol * i / steps)
                        time.sleep(interval)
                pygame.mixer.music.stop()
                pygame.mixer.music.set_volume(1.0)
            sfx_name = tcfg.get('end_sound', '')
            if sfx_name:
                sfx_path = _resolve_audio_file(sfx_name)
                if sfx_path:
                    play_sfx(str(sfx_path))
            end_scene = tcfg.get('end_scene', '')
            if end_scene:
                wled_set_scene(end_scene)
            disp_file = tcfg.get('end_display', '')
            if disp_file and timer_state.get('show_end_display', True):
                global _timer_pre_end_slide
                _timer_pre_end_slide = dict(current_slide)
                _broadcast_timer_display(disp_file)
            timer_state['visible_on_display'] = False
            broadcast('timer_expired', {})
            log.info("Timer: expired")

def start_timer_thread():
    global timer_thread, timer_stop_event
    timer_stop_event = threading.Event()
    timer_thread = threading.Thread(target=timer_worker, daemon=True)
    timer_thread.start()

def countdown_worker():
    while not countdown_stop_event.is_set():
        time.sleep(1)
        if not countdown_state['running']:
            continue
        countdown_state['seconds_remaining'] -= 1
        broadcast('countdown_state', countdown_state)
        # LED strip countdown fill — runs the full duration for games countdown
        if (countdown_state.get('countdown_leds')
                and 0 < countdown_state['seconds_remaining']):
            threading.Thread(target=_update_countdown_leds,
                             args=(countdown_state['seconds_remaining'],
                                   countdown_state['duration'], countdown_state),
                             daemon=True).start()
        if countdown_state['seconds_remaining'] <= 0:
            countdown_state['seconds_remaining'] = 0
            countdown_state['running'] = False
            countdown_state['expired'] = True
            sfx_name = countdown_state.get('end_sound', '')
            if sfx_name:
                sfx_path = _resolve_audio_file(sfx_name)
                if sfx_path:
                    play_sfx(str(sfx_path))
            disp_file = countdown_state.get('end_display', '')
            if disp_file and countdown_state.get('show_end_display', True):
                global _cd_pre_end_slide
                _cd_pre_end_slide = dict(current_slide)
                _broadcast_timer_display(disp_file)
            broadcast('countdown_expired', {})
            log.info("Countdown: expired")

def start_countdown_thread():
    global countdown_thread, countdown_stop_event
    countdown_stop_event = threading.Event()
    countdown_thread = threading.Thread(target=countdown_worker, daemon=True)
    countdown_thread.start()

def _resolve_audio_file(name: str, prefer_music: bool = False):
    """Return Path for audio filename, checking sfx/ and music/ dirs."""
    if not name:
        return None
    dirs = ['music', 'sfx'] if prefer_music else ['sfx', 'music']
    for d in dirs:
        p = ASSETS_DIR / d / name
        if p.exists():
            return p
    return None

def load_games() -> dict:
    try:
        with open(GAMES_FILE) as f:
            games = json.load(f)
    except Exception:
        return {}
    # Backfill a stable id onto any entry recorded before entries had one —
    # renaming/deleting a specific runner needs something to target that
    # isn't just "same label", since duplicate names are the normal case.
    changed = False
    for entries in games.values():
        for entry in entries:
            if 'id' not in entry:
                entry['id'] = uuid.uuid4().hex[:8]
                changed = True
    if changed:
        save_games(games)
    return games

def save_games(data: dict):
    try:
        with open(GAMES_FILE, 'w') as f:
            json.dump(data, f, indent=2)
    except Exception as e:
        log.error(f"save_games: {e}")

