# ── WLED HTTP API ──
_ip_resolve_cache    = {}    # hostname -> (ip, resolved_at)
_ip_resolve_lock     = threading.Lock()
_ip_resolve_inflight = set()  # hostnames currently being refreshed in the background
_IP_RESOLVE_TTL      = 60    # a pole reconnecting to the AP after a power blip or
                              # a wlan1-watchdog AP restart can come back with a
                              # different DHCP lease even with a reservation
                              # configured — this bounds how long a stale IP can
                              # survive on its own, see _invalidate_ip() for the
                              # faster path (a failed send invalidates immediately
                              # rather than waiting out the TTL)

def _do_resolve_ip(hostname):
    try:
        ip = socket.gethostbyname(hostname)
        with _ip_resolve_lock:
            _ip_resolve_cache[hostname] = (ip, time.time())
    except Exception:
        pass
    finally:
        with _ip_resolve_lock:
            _ip_resolve_inflight.discard(hostname)

def _resolve_ip_once(hostname):
    """Resolve a hostname (e.g. an mDNS pole-a.local address) to a literal
    IP. mDNS lookups on this network have measured up to ~8s under real
    field conditions (confirmed live, on both poles at different times) —
    requests' timeout= parameter does NOT bound this, since DNS/mDNS
    resolution happens before the socket-level timeout even starts. Every
    caller that talks to a pole node or WLED device — not just the DMX
    animation loop — used to eat that cost on every single call.

    This is now non-blocking for every caller except the very first one
    for a given hostname in the process's lifetime: a cached value (even
    if past its TTL) is returned immediately, with a background thread
    kicked off to refresh it. Only a hostname with NO cache entry at all
    blocks the caller — see _prewarm_ip_cache(), which resolves every
    known pole/WLED hostname once at startup so that cold-blocking case
    never happens on a live show. Falls back to the original hostname if
    resolution fails, so callers behave the same as passing the hostname
    straight through to requests.post()."""
    if not hostname:
        return hostname
    cached = _ip_resolve_cache.get(hostname)
    if cached:
        ip, resolved_at = cached
        if time.time() - resolved_at >= _IP_RESOLVE_TTL:
            with _ip_resolve_lock:
                if hostname not in _ip_resolve_inflight:
                    _ip_resolve_inflight.add(hostname)
                    threading.Thread(target=_do_resolve_ip, args=(hostname,), daemon=True).start()
        return ip
    # Nothing cached yet — nothing to hand back while refreshing in the
    # background, so this one call has to block on the lookup. A node
    # that's down at process start (or has never once resolved) failed
    # this same blocking lookup on every single call, not just the first —
    # _do_resolve_ip() only ever wrote the cache on success, so a
    # persistently-down node left nothing behind to short-circuit later
    # calls, and every one of them paid the same ~8s cost as the first.
    # Caching the fallback here too (same value already being returned)
    # means only the very first call ever blocks; every call after that
    # takes the normal non-blocking cached-return-plus-background-refresh
    # path, same as a node that resolved successfully.
    try:
        ip = socket.gethostbyname(hostname)
    except Exception:
        with _ip_resolve_lock:
            _ip_resolve_cache[hostname] = (hostname, time.time())
        return hostname
    with _ip_resolve_lock:
        _ip_resolve_cache[hostname] = (ip, time.time())
    return ip

def _invalidate_ip(hostname):
    """Force the next _resolve_ip_once() call for this hostname to refresh in
    the background instead of coasting on the full TTL. Call this when a
    request to the cached IP fails — a stale IP after a pole reconnects with
    a new DHCP lease should recover in roughly one failed send, not up to a
    minute later.

    Deliberately does NOT drop the cache entry outright (the original
    implementation did) — with nothing cached at all, _resolve_ip_once()'s
    only option is a synchronous, blocking lookup (measured up to ~8s on
    this network). A node that's genuinely offline (not just DHCP-shuffled)
    fails, and therefore invalidates, on every single send — which turned
    every subsequent call into another blocking lookup, and since that call
    happens on the caller's own thread (e.g. the DMX animation loop, before
    it even gets to the next node in the same frame), a permanently-down
    node stalled everything sharing that thread for as long as it stayed
    down. Forcing the existing entry's timestamp to already-expired instead
    keeps the fast, non-blocking path — return the last-known IP
    immediately, refresh in the background — even while a node stays down."""
    cached = _ip_resolve_cache.get(hostname)
    if cached:
        ip, _ = cached
        _ip_resolve_cache[hostname] = (ip, 0)

def _prewarm_ip_cache():
    """Resolve every configured pole-node/WLED hostname once, up front, in
    the background — so the one truly-blocking case in _resolve_ip_once()
    (a hostname with no cache entry yet) happens at process startup rather
    than mid-show on whatever request/animation/poll loop happens to touch
    that hostname first."""
    cfg = load_config()
    hosts = set()
    for n in cfg.get('pole_nodes', []):
        if n.get('ip'):
            hosts.add(n['ip'])
    for d in cfg.get('wled_devices', []):
        if d.get('ip'):
            hosts.add(d['ip'])
    for h in hosts:
        threading.Thread(target=_do_resolve_ip, args=(h,), daemon=True).start()

def wled_set_scene(scene_id):
    """Apply a lighting scene to all WLED devices."""
    global _scene_apply_epoch
    _scene_apply_epoch += 1
    my_epoch = _scene_apply_epoch
    scenes = {s['id']: s for s in config.get('scenes', [])}
    if scene_id not in scenes:
        log.warning(f"Scene not found: {scene_id}")
        return
    scene = scenes[scene_id]
    devices = {d['id']: d for d in config.get('wled_devices', [])}
    zones = scene.get('zones', {})
    def send_zone(device_id, seg_id, effect, color=None, brightness=75, speed=50):
        if device_id not in devices:
            return
        ip = devices[device_id]['ip']
        _WLED_FX = {'solid': 0, 'fire': 35, 'rainbow': 9, 'strobe': 11,
                    'fade': 7, 'theater': 15, 'twinkle': 44}
        fx_id = _WLED_FX.get(effect)
        if fx_id is None:
            log.warning(f"WLED: unknown effect {effect!r} for {device_id}, falling back to solid")
            fx_id = 0
        payload = {
            'seg': [{
                'id': seg_id,
                'on': brightness > 0,
                'bri': int(brightness * 2.55),
                'fx': fx_id,
                'sx': speed,
            }]
        }
        if color:
            r, g, b = int(color[1:3], 16), int(color[3:5], 16), int(color[5:7], 16)
            payload['seg'][0]['col'] = [[r, g, b]]
        if _scene_apply_epoch != my_epoch:
            return  # a newer scene apply has already started — don't send a stale color
        try:
            requests.post(f"http://{_resolve_ip_once(ip)}/json/state", json=payload, timeout=0.5)
        except Exception as e:
            _invalidate_ip(ip)
            log.warning(f"WLED {device_id} unreachable: {e}")
    threads = []
    for zone_key, zone_cfg in zones.items():
        if '_pole' in zone_key:
            parts = zone_key.split('_pole_')
            device_id = parts[0] + '_pole' if len(parts) > 1 else zone_key
            seg_name = parts[1] if len(parts) > 1 else 'main'
            device = devices.get(device_id)
            if device:
                seg_id = next((s['id'] for s in device.get('segments', [])
                               if s['name'] == seg_name), 0)
                t = threading.Thread(
                    target=send_zone,
                    args=(device_id, seg_id,
                          zone_cfg.get('effect', 'solid'),
                          zone_cfg.get('color'),
                          zone_cfg.get('brightness', 75),
                          zone_cfg.get('speed', 50)),
                    daemon=True
                )
                threads.append(t)
        else:
            t = threading.Thread(
                target=send_zone,
                args=(zone_key, 0,
                      zone_cfg.get('effect', 'solid'),
                      zone_cfg.get('color'),
                      zone_cfg.get('brightness', 75),
                      zone_cfg.get('speed', 50)),
                daemon=True
            )
            threads.append(t)
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=0.6)   # tighter than original 1.0s; matches the 0.5s HTTP timeout

    # Apply pole flashlight modes — run in background so BLE latency doesn't block the caller
    def _apply_pole_lights():
        from SolixBLE.states import LightStatus
        _ls_map = {'off': LightStatus.OFF, 'low': LightStatus.LOW, 'high': LightStatus.HIGH, 'sos': LightStatus.SOS}
        for pole_label, mode in scene.get('poles', {}).items():
            ls = _ls_map.get((mode or '').lower())
            if ls is None:
                continue
            addr = next((u['address'] for u in config.get('battery_units', []) if u['label'] == pole_label), None)
            if addr:
                ok, err = _batt_cmd(addr, lambda d, _ls=ls: d.set_light_mode(_ls))
                if not ok:
                    log.warning(f'Scene pole light [{pole_label}]: {err}')
    threading.Thread(target=_apply_pole_lights, daemon=True).start()

    # Apply DMX fixture values to pole nodes — one thread per node so a
    # slower/weaker connection on one pole doesn't delay another (nodes were
    # previously sent sequentially in a single thread, and a tight 0.5s
    # timeout on a marginal WiFi link could abort mid-transfer, leaving the
    # ESP32 parsing a truncated JSON payload — manifesting as random-looking
    # colors on whichever node has a weaker connection). 2s matches the
    # timeout already used by Admin's manual per-fixture test fire, which
    # has never shown this problem.
    def _apply_dmx_node(node_id, fixtures_vals, node, fixture_types):
        global _last_scene_dmx
        fixture_defs = {f['id']: f for f in node.get('fixtures', [])}
        payload_raw = []
        for fix_id, channels in fixtures_vals.items():
            if not channels:
                continue
            fix = fixture_defs.get(fix_id)
            if not fix:
                continue
            dim_mask = _build_dim_mask(fix, fixture_types)
            payload_raw.append({'start': fix['start'], 'channels': list(channels),
                                'dim_mask': dim_mask})
        if payload_raw and _scene_apply_epoch == my_epoch:
            _last_scene_dmx[node_id] = payload_raw
            scaled = [{'start': f['start'],
                       'channels': _dim_channels(f['channels'], _master_dim, f['dim_mask'])}
                      for f in payload_raw]
            hostname = node['ip']
            def _post():
                try:
                    requests.post(f"http://{_resolve_ip_once(hostname)}/dmx",
                                  json={'fixtures': scaled}, timeout=2)
                except Exception as e:
                    _invalidate_ip(hostname)
                    log.warning(f"Pole node {node_id} DMX error: {e}")
            _post()
            # A DMX animation loop cancelled by this same scene-apply can have
            # one last frame already dispatched to its own background thread
            # a few ms before the stop event was set — that request is still
            # in flight over WiFi and its response can land after this one,
            # silently overwriting these values with a stale animated color
            # (confirmed live: a walkup's trailing frame landed ~10ms after
            # the Stage scene's correct wash value and clobbered it). Resend
            # once more after any such straggler has had time to land, same
            # pattern _wled_fire_preset already uses for the same reason.
            # Skipped if a newer scene has since superseded this one.
            time.sleep(0.25)
            if _scene_apply_epoch == my_epoch:
                _post()

    dmx_block = scene.get('dmx', {})
    if dmx_block:
        _all_pole_nodes = config.get('pole_nodes', [])
        _nodes_by_id    = {n['id']: n for n in _all_pole_nodes}
        _fixture_types  = config.get('fixture_types', {})
        # "Pole B follows Pole A": scene stores only the leader (first pole
        # node)'s values; every other node's fixtures are computed here from
        # the leader's, matched by fixture id — not saved/duplicated, so
        # editing the leader's look later automatically carries through on
        # the next fire with no re-sync step needed.
        if scene.get('dmx_poles_match') and _all_pole_nodes:
            leader_id = _all_pole_nodes[0]['id']
            leader_vals = dmx_block.get(leader_id, {})
            dmx_block = {leader_id: leader_vals}
            for node in _all_pole_nodes[1:]:
                dmx_block[node['id']] = dict(leader_vals)
        for node_id, fixtures_vals in dmx_block.items():
            node = _nodes_by_id.get(node_id)
            if not node or not node.get('ip'):
                continue
            threading.Thread(target=_apply_dmx_node,
                              args=(node_id, fixtures_vals, node, _fixture_types),
                              daemon=True).start()

    # Cancel any running DMX animation, then start a new one if this scene defines one
    global _dmx_anim_stop
    _dmx_anim_stop.set()
    _dmx_anim_stop = threading.Event()

    # Fire WLED preset on all pole nodes if scene specifies one — one thread
    # per node so they all receive the command at essentially the same
    # moment, instead of node 2 waiting for node 1's HTTP call to finish.
    wled_preset = scene.get('wled_preset')
    wled_preset_by_node = scene.get('wled_preset_by_node') or {}
    if wled_preset is not None or wled_preset_by_node:
        _pole_nodes = config.get('pole_nodes', [])
        def _fire_one(ip, ps):
            if _scene_apply_epoch != my_epoch:
                return
            _wled_fire_preset(ip, ps)
        for node in _pole_nodes:
            ip = node.get('ip')
            if not ip:
                continue
            # A per-node override wins if this scene has one for this node;
            # otherwise every node falls back to the shared preset.
            ps = wled_preset_by_node.get(node['id'], wled_preset)
            if ps is None:
                continue
            threading.Thread(target=_fire_one, args=(ip, ps), daemon=True).start()

    # Start DMX animation loop if scene defines one
    dmx_anim = scene.get('dmx_animation')
    if dmx_anim and dmx_anim.get('frames'):
        transition_s = (dmx_anim.get('interval_ms') or 400) / 1000.0
        frames       = dmx_anim['frames']
        nodes_map    = {n['id']: n for n in config.get('pole_nodes', [])}
        # fixture_types is stored as a dict keyed by type name (see the
        # working usage a few lines up, config.get('fixture_types', {})) —
        # this was iterating it as if it were a list, which yields its
        # string keys, not the type dicts, and crashed every time a scene
        # with a DMX animation fired.
        fixture_types_snap = dict(config.get('fixture_types', {}))
        loop_count   = max(0, int(dmx_anim.get('loops') or 0))
        stop_ev      = _dmx_anim_stop
        def _run_dmx_anim(_frames=frames, _nodes=nodes_map, _stop=stop_ev, _tv=transition_s,
                          _fixture_types=fixture_types_snap, _loops=loop_count):
            global _dmx_anim_active
            _dmx_anim_active = True

            # Pole node addresses are mDNS hostnames (pole-a.local, pole-b.local),
            # and requests.post() re-resolves the hostname fresh on every single
            # call — with this loop firing up to ~25 requests/sec/node, any node
            # whose mDNS resolution is slow pays that cost on every request, not
            # once. That's what "doesn't even animate" was: one pole's resolution
            # was consistently taking ~8s per lookup (confirmed live — that
            # pole's requests took ~8s exact, over and over, while the other
            # pole stayed near-instant the whole time), so the per-node
            # in-flight guard correctly kept it from piling up, but it also
            # meant that pole got an update roughly once every 8 seconds instead
            # of ~12/sec.
            #
            # _resolve_ip_once() is called on every send below rather than once
            # up front, so a scene left animating for a long time (not just a
            # fresh fire) still picks up a pole reconnecting with a new DHCP
            # lease after a power blip or an AP restart, and a failed send
            # invalidates the cache immediately (see _invalidate_ip below) so
            # recovery doesn't wait out the TTL. This call happens on the main
            # loop thread (not inside _send_one's background thread), which
            # used to mean an expired cache entry blocked the ENTIRE step loop
            # for as long as the mDNS lookup took (measured up to 8s live) —
            # this was the actual cause of "doesn't even animate" turning into
            # periodic full-animation freezes later on. _resolve_ip_once() is
            # now non-blocking for any hostname that's ever been resolved
            # before (it hands back the cached value and refreshes in the
            # background), so this call can no longer stall the loop.

            # Tracks which nodes currently have a DMX POST in flight. Without
            # this, a node that takes even slightly longer than one 40ms step
            # to respond (very plausible over WiFi) accumulates a growing
            # backlog of overlapping requests — and since HTTP responses can
            # land out of order, a newer request can be overtaken by an
            # older, now-stale one completing later, applying a stale frame
            # after a newer one. That's what "wonky after a couple of
            # cycles" was: the backlog needs a few seconds to build up
            # before it's visible, then it only gets worse. A real-time loop
            # like this should drop a step for a busy node rather than queue
            # it — the next step 40ms later supersedes it anyway.
            _inflight      = set()
            _inflight_lock = threading.Lock()

            def _send_one(node, payload, node_id, hostname):
                try:
                    requests.post(f"http://{node['ip']}/dmx",
                                  json={'fixtures': payload}, timeout=2)
                except Exception:
                    _invalidate_ip(hostname)
                finally:
                    with _inflight_lock:
                        _inflight.discard(node_id)

            def _send(frame):
                # Fire each node in its own thread — this loop runs at ~25Hz,
                # and blocking on a slow/marginal node's HTTP response here
                # would stall the whole animation's timing, backing up steps
                # and then bursting them out once the slow request finally
                # returns (looks exactly like fast strobing on the affected
                # node). Firing and moving on keeps the step timer accurate
                # regardless of how any one node's connection is behaving.
                for node_id, fix_vals in frame.items():
                    node = _nodes.get(node_id)
                    if not node or not node.get('ip'):
                        continue
                    with _inflight_lock:
                        if node_id in _inflight:
                            continue  # previous send to this node still in flight — drop this step
                        _inflight.add(node_id)
                    hostname = node['ip']
                    node = {**node, 'ip': _resolve_ip_once(hostname)}
                    fix_map = {f['id']: f for f in node.get('fixtures', [])}
                    payload = []
                    for fix_id, channels in fix_vals.items():
                        fix = fix_map.get(fix_id)
                        if fix and channels:
                            mask = _build_dim_mask(fix, _fixture_types)
                            payload.append({'start': fix['start'],
                                            'channels': _dim_channels(channels, _master_dim, mask)})
                    if payload:
                        threading.Thread(target=_send_one, args=(node, payload, node_id, hostname), daemon=True).start()
                    else:
                        with _inflight_lock:
                            _inflight.discard(node_id)

            # Hard-cut between frames — send a look's exact values once, hold
            # for _tv, then jump straight to the next look. No interpolation,
            # so no intermediate/in-between values are ever sent at all. This
            # replaced a smooth-fade interpolator: every animation frame used
            # to be re-sent every ~200ms throughout the whole transition
            # (n_steps POSTs per fade), which meant a sustained burst of
            # WiFi RX activity on the pole node for as long as the animation
            # ran. Chris's read of the failure pattern (only during
            # animations, gets worse over time, needs the fixture's own IR
            # remote to recover) points at the pole node's own WiFi radio
            # activity injecting electrical noise into its RS485 output —
            # cutting each transition down to exactly one send removes most
            # of that sustained activity outright, regardless of whether
            # that mechanism turns out to be the whole story.
            #
            # loops=0 (or unset) means "forever, until a new scene fires" —
            # the long-standing behavior. A finite loop count stops the loop
            # on its own once it's played through the whole frame sequence
            # that many times, holding on the last frame reached rather than
            # waiting on a new scene to cut it off.
            max_transitions = (_loops * len(_frames)) if _loops else None

            try:
                if len(_frames) == 1:
                    _send(_frames[0])
                    _stop.wait()
                    return

                fi = 0
                transitions_done = 0
                while not _stop.is_set():
                    if max_transitions is not None and transitions_done >= max_transitions:
                        break
                    _send(_frames[fi % len(_frames)])
                    if _stop.wait(_tv):
                        return
                    fi += 1
                    transitions_done += 1
            finally:
                _dmx_anim_active = False

        threading.Thread(target=_run_dmx_anim, daemon=True).start()

    global current_scene
    current_scene = scene_id
    log.info(f"Scene applied: {scene_id}")
    broadcast('scene_changed', {'scene': scene_id})

def wled_set_color(device_id, color, brightness=75, seg_id=0):
    """Set a specific WLED device to a solid color."""
    devices = {d['id']: d for d in config.get('wled_devices', [])}
    if device_id not in devices:
        return
    ip = devices[device_id]['ip']
    r, g, b = int(color[1:3], 16), int(color[3:5], 16), int(color[5:7], 16)
    payload = {
        'seg': [{'id': seg_id, 'on': True,
                 'bri': int(brightness * 2.55),
                 'fx': 0, 'col': [[r, g, b]]}]
    }
    try:
        requests.post(f"http://{_resolve_ip_once(ip)}/json/state", json=payload, timeout=0.5)
    except Exception as e:
        _invalidate_ip(ip)
        log.warning(f"WLED {device_id} unreachable: {e}")

# ── KILL LIGHTS ──
def kill_lights():
    """Send brightness 0 to every WLED device and all-zeros DMX to every pole node.

    Every send is a fire-and-forget single attempt with only a log.warning on
    failure — unlike scene-fire (_apply_dmx_node), which learned this lesson
    and resends once more ~0.25s later as insurance against a transient miss.
    A blackout that silently fails to land is worse than a scene that does:
    there's no next scene fire to correct it, so a fixture can be left on
    for hours (confirmed live — this exact gap left a pole node lit
    overnight after kill_lights ran). Each off-send now retries the same way
    scene-fire already does.
    """
    cfg = config
    off_payload = json.dumps({'bri': 0, 'on': False})
    headers = {'Content-Type': 'application/json'}
    def _wled_off(ip):
        for attempt in range(2):
            try:
                requests.post(f'http://{_resolve_ip_once(ip)}/json/state', data=off_payload,
                              headers=headers, timeout=0.8)
                return
            except Exception as e:
                _invalidate_ip(ip)
                if attempt == 0:
                    time.sleep(0.3)
                else:
                    log.warning(f"WLED {ip} kill unreachable: {e}")
    def _dmx_off(ip):
        # start=15/10ch is the 'par' fixture — added after this function was
        # first written, and missed here even though scene-fire and kill_lights
        # elsewhere both know about it. Without this, kill_lights never turned
        # the PAR fixture off at all, network reliability aside.
        fixtures = [
            {'start': 1,  'channels': [0] * 6},
            {'start': 7,  'channels': [0] * 8},
            {'start': 15, 'channels': [0] * 10},
        ]
        for attempt in range(2):
            try:
                requests.post(f'http://{_resolve_ip_once(ip)}/dmx', json={'fixtures': fixtures}, timeout=0.8)
                return
            except Exception as e:
                _invalidate_ip(ip)
                if attempt == 0:
                    time.sleep(0.3)
                else:
                    log.warning(f"Pole node {ip} kill unreachable: {e}")
    threads = []
    for d in cfg.get('wled_devices', []):
        if d.get('ip'):
            threads.append(threading.Thread(target=_wled_off, args=(d['ip'],), daemon=True))
    for n in cfg.get('pole_nodes', []):
        if n.get('ip'):
            threads.append(threading.Thread(target=_wled_off, args=(n['ip'],), daemon=True))
            threads.append(threading.Thread(target=_dmx_off, args=(n['ip'],), daemon=True))
    for t in threads:
        t.start()
    log.info(f"kill_lights: blanked {len(cfg.get('wled_devices',[]))} WLED + {len(cfg.get('pole_nodes',[]))} nodes")

# ── KILL EVERYTHING ──
def kill_everything():
    """
    Emergency stop. Stops all audio, turns off all lights.
    Does NOT lose program position or reset timer to zero.
    """
    global _walkup_fade_cancel, _macro_cancel
    log.info("KILL EVERYTHING fired")
    _walkup_fade_cancel.set()
    _walkup_fade_cancel = threading.Event()
    _macro_cancel.set()  # stops any running macro, including a looping one
    _macro_cancel = threading.Event()
    stop_audio()
    timer_state['running'] = False
    kill_lights()
    broadcast('kill_all', {})

# ── WALKUP MACRO ──
def _versioned_walkup_file(base_dir, item_id, filename):
    """Append a cache-busting ?v=<mtime> to a walkup video filename.

    Uploading a replacement circle/role/game-entry video always overwrites a
    fixed filename (walkup.mp4, walkup_intro.mp4) — the URL never changes.
    Both the browser's own HTTP cache (/assets/ is served with a 1hr
    max-age) and this app's own preload caches in display.html
    (_preloadPool, _wuWarm — keyed purely by URL, no TTL) would otherwise
    keep serving the old file indefinitely after a swap, until the kiosk
    happens to reload. Appending the file's mtime makes a replaced file
    produce a new URL, forcing a fresh fetch, while an unchanged file keeps
    its URL and stays cached/preloaded as intended.
    """
    if not filename:
        return filename
    try:
        mtime = int((base_dir / item_id / filename).stat().st_mtime)
        return f'{filename}?v={mtime}'
    except OSError:
        return filename

def fire_walkup(circle_id=None, role_id=None, show_flow_idx=None):
    """Fire a complete walk-up sequence for a circle or role."""
    cfg = config  # use in-memory copy — eliminates SD card read on every walkup
    if circle_id:
        items = [c for c in cfg.get('circles', []) if c['id'] == circle_id]
        item = items[0] if items else None
        item_type = 'circle'
    elif role_id:
        items = [r for r in cfg.get('roles', []) if r['id'] == role_id]
        item = items[0] if items else None
        item_type = 'role'
    else:
        return
    if not item:
        log.error(f"Walk-up target not found: {circle_id or role_id}")
        return
    global _walkup_fade_cancel
    _walkup_fade_cancel.set()           # cancel any previous auto-fade
    _walkup_fade_cancel = threading.Event()
    cancel = _walkup_fade_cancel

    color        = item.get('color',  '#FFFFFF')
    color2       = item.get('color2', '#000000')
    walkup_cfg   = item.get('walkup', {})
    assets_cfg   = item.get('assets', {})
    # Resolve walkup music: library ref takes priority over direct upload
    music_lib    = assets_cfg.get('walkup_music_lib', '')
    if music_lib:
        music_file = ASSETS_DIR / 'music' / music_lib
    else:
        music_file = ASSETS_DIR / ('circles' if item_type == 'circle' else 'roles') \
                     / item['id'] / assets_cfg.get('walkup_music', '')
    # Resolve logo URL for display broadcast
    logo_lib     = assets_cfg.get('logo_lib', '')
    logo_url     = f'/assets/display/{logo_lib}' if logo_lib else ''
    walkup_scene = walkup_cfg.get('walkup_scene') or None
    stage_scene  = walkup_cfg.get('stage_scene')  or 'campfire'

    # Lighting at walk-up start: configured scene, or color-flash fallback
    def fire_walkup_lighting():
        if walkup_scene:
            wled_set_scene(walkup_scene)
        else:
            for device in cfg.get('wled_devices', []):
                if device['id'] in ('ezup_ceil',):
                    continue
                wled_set_color(device['id'], color, brightness=80)

    _walkup_dir = ASSETS_DIR / ('circles' if item_type == 'circle' else 'roles')
    display_payload = {
        'id':              item['id'],
        'name':            item.get('name', ''),
        'color':           color,
        'color2':          color2,
        'type':            item_type,
        'number':          item.get('number', ''),
        'music':           item.get('assets', {}).get('walkup_music', ''),
        'logo':            item.get('assets', {}).get('logo', ''),
        'logo_url':        logo_url,
        'duration':        walkup_cfg.get('duration', 30),
        'animation':       _versioned_walkup_file(_walkup_dir, item['id'], item.get('assets', {}).get('animation',       '')),
        'animation_intro': _versioned_walkup_file(_walkup_dir, item['id'], item.get('assets', {}).get('animation_intro', '')),
        'hide_name':       walkup_cfg.get('hide_name', False),
    }
    next_preload = _get_next_walkup_preload(cfg, show_flow_idx)
    if next_preload:
        display_payload['next_preload'] = next_preload

    def play_music():
        if music_file.exists() and music_file.is_file():
            vol_trim = walkup_cfg.get('volume_trim', 100)
            base_vol = audio_state['volume']
            trimmed  = max(0, min(100, int(base_vol * vol_trim / 100)))
            # Crossfade fades old music; display fires the instant new file is loaded,
            # just before play() — so sound and video start at the same moment
            play_audio(
                str(music_file),
                volume=trimmed,
                start_pos=walkup_cfg.get('start_time', 0),
                crossfade_ms=1000,
                on_loaded=lambda: broadcast('display_walkup', display_payload),
            )
            my_session = _audio_session
            duration = walkup_cfg.get('duration', 30)
            fade_dur = walkup_cfg.get('fade_duration', 3)
            def auto_fade(ev=cancel, sess=my_session):
                if ev.wait(timeout=duration):
                    return  # cancelled by new walkup or kill
                if _audio_session != sess:
                    return  # audio changed (playlist, macro, etc.) — don't fade
                fade_audio(fade_dur)
                if ev.wait(timeout=fade_dur + 0.5):
                    return
                if _audio_session == sess:
                    wled_set_scene(stage_scene)
            threading.Thread(target=auto_fade, daemon=True).start()
        else:
            if music_file.name and not music_file.exists():
                log.warning(f"Walk-up music not found: {music_file}")
            if pygame.mixer.music.get_busy():
                fade_audio(3)
            if not cancel.is_set():
                broadcast('display_walkup', display_payload)
            duration = walkup_cfg.get('duration', 30)
            def auto_fade_no_music(ev=cancel):
                if ev.wait(timeout=duration):
                    return  # cancelled by new walkup or kill
                wled_set_scene(stage_scene)
            threading.Thread(target=auto_fade_no_music, daemon=True).start()

    # Track current circle
    global current_circle
    current_circle = item['id']

    # Lighting and LED colour animation fire immediately; music + display fire together
    # after the 1-second crossfade (new music starts exactly when display appears)
    threading.Thread(target=fire_walkup_lighting, daemon=True).start()
    threading.Thread(target=play_music, daemon=True).start()
    walkup_preset = walkup_cfg.get('wled_preset')  # optional WLED playlist/preset number
    # Fire crowd lights if: explicit preset set, OR circle/role with colors but no explicit scene
    # Skip crowd animation when walkup_scene is set — the scene owns the pole lighting
    role_default_anim = role_id and color and color2 and not walkup_scene and walkup_preset is None
    if cfg.get('crowd_lights') and (walkup_preset is not None or (circle_id and color and color2 and not walkup_scene) or role_default_anim):
        threading.Thread(
            target=_walkup_color_anim,
            args=(walkup_preset, color, color2, cancel, cfg),
            daemon=True
        ).start()
    log.info(f"Walk-up fired: {item.get('name')}")


def fire_game_entry(entry_id, reveal_url=None):
    """Fire a game entry sequence (music + display + lighting), like fire_walkup but no circle/role specifics.
    reveal_url: when set, the display client reveals the preloaded game at this URL the instant
    the intro video's own onended fires — exact sync to real playback, no blind duration guess."""
    cfg = config
    items = [e for e in cfg.get('game_entries', []) if e['id'] == entry_id]
    item  = items[0] if items else None
    if not item:
        log.error(f"Game entry not found: {entry_id}")
        return
    global _walkup_fade_cancel
    _walkup_fade_cancel.set()
    _walkup_fade_cancel = threading.Event()
    cancel = _walkup_fade_cancel

    walkup_cfg = item.get('walkup', {})
    assets_cfg = item.get('assets', {})
    music_lib  = assets_cfg.get('walkup_music_lib', '')
    if music_lib:
        music_file = ASSETS_DIR / 'music' / music_lib
    else:
        music_file = ASSETS_DIR / 'game_entries' / item['id'] / assets_cfg.get('walkup_music', '')
    walkup_scene = walkup_cfg.get('walkup_scene') or None
    stage_scene  = walkup_cfg.get('stage_scene')  or 'campfire'

    def fire_lighting():
        if walkup_scene:
            wled_set_scene(walkup_scene)

    display_payload = {
        'id':              item['id'],
        'name':            item.get('name', ''),
        'color':           '#F5A623',
        'color2':          '#000000',
        'type':            'game_entry',
        'number':          '',
        'music':           assets_cfg.get('walkup_music', ''),
        'logo':            '',
        'logo_url':        '',
        'duration':        walkup_cfg.get('duration', 30),
        'animation':       _versioned_walkup_file(ASSETS_DIR / 'game_entries', item['id'], assets_cfg.get('animation',       '')),
        'animation_intro': _versioned_walkup_file(ASSETS_DIR / 'game_entries', item['id'], assets_cfg.get('animation_intro', '')),
        'hide_name':       walkup_cfg.get('hide_name', False),
        'muted':           walkup_cfg.get('muted', True),
        'reveal_game_url': reveal_url,
    }

    def play_music():
        if music_file.exists() and music_file.is_file():
            vol_trim = walkup_cfg.get('volume_trim', 100)
            base_vol = audio_state['volume']
            trimmed  = max(0, min(100, int(base_vol * vol_trim / 100)))
            play_audio(
                str(music_file),
                volume=trimmed,
                start_pos=walkup_cfg.get('start_time', 0),
                crossfade_ms=1000,
                on_loaded=lambda: broadcast('display_walkup', display_payload),
            )
            my_session = _audio_session
            duration   = walkup_cfg.get('duration', 30)
            fade_dur   = walkup_cfg.get('fade_duration', 3)
            def auto_fade(ev=cancel, sess=my_session):
                if ev.wait(timeout=duration):
                    return
                if _audio_session != sess:
                    return
                fade_audio(fade_dur)
                if ev.wait(timeout=fade_dur + 0.5):
                    return
                if _audio_session == sess:
                    wled_set_scene(stage_scene)
            threading.Thread(target=auto_fade, daemon=True).start()
        else:
            if music_file.name and not music_file.exists():
                log.warning(f"Game entry music not found: {music_file}")
            if pygame.mixer.music.get_busy():
                fade_audio(3)
            if not cancel.is_set():
                broadcast('display_walkup', display_payload)
            duration = walkup_cfg.get('duration', 30)
            def auto_fade_no_music(ev=cancel):
                if ev.wait(timeout=duration):
                    return
                wled_set_scene(stage_scene)
            threading.Thread(target=auto_fade_no_music, daemon=True).start()

    global current_circle
    current_circle = item['id']
    threading.Thread(target=fire_lighting, daemon=True).start()
    threading.Thread(target=play_music,    daemon=True).start()
    walkup_preset = walkup_cfg.get('wled_preset')
    if cfg.get('crowd_lights') and walkup_preset is not None:
        threading.Thread(
            target=_walkup_color_anim,
            args=(walkup_preset, '#F5A623', '#000000', cancel, cfg),
            daemon=True
        ).start()
    log.info(f"Game entry fired: {item.get('name')}")


# ════════════════════════════════════════════
# AUDIO NORMALIZATION
# ════════════════════════════════════════════

_NORM_EXTS = {'.mp3', '.wav', '.wave', '.ogg', '.flac', '.aac', '.m4a'}
_normalize_state = {
    'running':  False,
    'done':     0,
    'total':    0,
    'current':  '',
    'errors':   [],
    'last_run': int(NORM_STAMP.stat().st_mtime) if NORM_STAMP.exists() else 0,
}

def _normalize_file_2pass(fp: Path):
    """Two-pass EBU R128 normalization to -14 LUFS. Overwrites file in-place."""
    ext = fp.suffix.lower()

    # Pass 1 — measure loudness
    r1 = subprocess.run(
        ['ffmpeg', '-nostdin', '-i', str(fp),
         '-af', 'loudnorm=I=-14:TP=-1.5:LRA=11:print_format=json',
         '-f', 'null', '-'],
        capture_output=True, text=True
    )
    idx_start = r1.stderr.rfind('{')
    idx_end   = r1.stderr.rfind('}')
    if idx_start == -1 or idx_end == -1 or idx_end < idx_start:
        raise RuntimeError(f"loudnorm pass 1 produced no JSON for {fp.name}")
    stats = json.loads(r1.stderr[idx_start:idx_end + 1])

    # Pass 2 — apply linear normalization
    af2 = (
        f"loudnorm=I=-14:TP=-1.5:LRA=11:linear=true:"
        f"measured_I={stats['input_i']}:"
        f"measured_TP={stats['input_tp']}:"
        f"measured_LRA={stats['input_lra']}:"
        f"measured_thresh={stats['input_thresh']}:"
        f"offset={stats['target_offset']}"
    )
    codec = {
        '.mp3':  ['-c:a', 'libmp3lame', '-q:a', '2'],
        '.wav':  ['-c:a', 'pcm_s16le'],
        '.wave': ['-c:a', 'pcm_s16le'],
    }.get(ext, [])

    tmp = fp.with_suffix('.normalizing' + ext)
    try:
        subprocess.run(
            ['ffmpeg', '-nostdin', '-y', '-i', str(fp),
             '-af', af2, '-ar', '44100'] + codec + [str(tmp)],
            capture_output=True, text=True, check=True
        )
        tmp.replace(fp)
    except Exception:
        if tmp.exists():
            tmp.unlink()
        raise

def _collect_norm_files(mode: str) -> list:
    cutoff = NORM_STAMP.stat().st_mtime if (mode == 'new' and NORM_STAMP.exists()) else 0
    seen   = set()
    files  = []

    def _add(f: Path):
        key = str(f)
        if key in seen or f.name.startswith('._'):
            return
        seen.add(key)
        if cutoff == 0 or f.stat().st_mtime > cutoff:
            files.append(f)

    # Local assets: music library + per-circle + per-role (sfx intentionally excluded)
    local_dirs = [ASSETS_DIR / 'music']
    for base in (ASSETS_DIR / 'circles', ASSETS_DIR / 'roles'):
        if base.exists():
            local_dirs.extend(d for d in base.iterdir() if d.is_dir())
    for d in local_dirs:
        if d.exists():
            for f in sorted(d.iterdir()):
                if f.is_file() and f.suffix.lower() in _NORM_EXTS:
                    _add(f)

    return files

def _run_normalization(mode: str):
    if not shutil.which('ffmpeg'):
        _normalize_state.update({'running': False, 'errors': ['ffmpeg not found on PATH']})
        return
    files = _collect_norm_files(mode)
    _normalize_state.update({'total': len(files), 'done': 0, 'errors': [], 'current': ''})
    for fp in files:
        _normalize_state['current'] = fp.name
        try:
            _normalize_file_2pass(fp)
            log.info(f"Normalized: {fp.name}")
        except Exception as e:
            log.error(f"Normalize error {fp.name}: {e}")
            _normalize_state['errors'].append(fp.name)
        _normalize_state['done'] += 1
    NORM_STAMP.parent.mkdir(parents=True, exist_ok=True)
    NORM_STAMP.touch()
    _normalize_state.update({
        'running':  False,
        'current':  '',
        'last_run': int(NORM_STAMP.stat().st_mtime),
    })
    log.info(f"Normalization done: {len(files)} files, {len(_normalize_state['errors'])} errors")

