    card['id'] = cid
    idx = next((i for i, c in enumerate(cards) if c['id'] == cid), None)
    if idx is not None:
        existing = cards[idx]
        for side in ('left', 'right'):
            if existing.get(side, {}).get('image') and not card.get(side, {}).get('image'):
                card.setdefault(side, {})['image'] = True
