def _chairs_play_cue_file(filename):
    """stop_sfx values come from the merged sfx+music picker — check both dirs."""
    for sub in ('sfx', 'music'):
        fp = ASSETS_DIR / sub / filename
        if fp.exists():
            play_sfx(str(fp))
            return
    log.warning(f"Musical Chairs stop cue file not found: {filename}")

def _fire_fallback_screen(cfg_data):
    """Push a game config's own headline/text/image straight to the display —
    no separate Slide or Game Entry to create and pick, it's just built in.
    Shared by any game type whose config has fallback_headline/fallback_text/
    fallback_image fields (currently Musical Chairs and Timed Competition)."""
    global current_slide
    slide_data = {
        'template': 'spotlight',
        'headline': cfg_data.get('fallback_headline', ''),
        'subtitle': cfg_data.get('fallback_text', ''),
        'image':    ('display/' + cfg_data['fallback_image']) if cfg_data.get('fallback_image') else '',
    }
    current_slide = slide_data
    _ensure_display_for('display_slide', slide_data)

def _chairs_do_stop(cfg_data):
    """Pause (not stop) so the next START resumes from the same position instead
    of restarting the song — real musical chairs doesn't rewind between rounds."""
    global chairs_state
    try:
        pygame.mixer.music.pause()
        audio_state['paused'] = True
        broadcast('audio_state', audio_state)
    except Exception as e:
        log.warning(f"Musical Chairs pause error: {e}")
    with _chairs_lock:
        chairs_state['playing'] = False
    broadcast('chairs_state', chairs_state)
    scene_id = (cfg_data or {}).get('stop_scene')
    if scene_id:
        # Threaded like every other scene-fire call site (e.g. /api/lights/scene) —
        # wled_set_scene() blocks its caller for up to ~0.6s waiting on WLED HTTP
        # responses, and with gunicorn running a single worker, calling it inline
        # here stalled the STOP request (and the whole app) for that whole window.
        threading.Thread(target=wled_set_scene, args=(scene_id,), daemon=True).start()
    sfx_name = (cfg_data or {}).get('stop_sfx')
    if sfx_name:
        _chairs_play_cue_file(sfx_name)

@app.route('/api/games/chairs/state')
def api_games_chairs_state():
    return jsonify(chairs_state)

@app.route('/api/games/chairs/start', methods=['POST'])
def api_games_chairs_start():
    global chairs_state, _chairs_stop_token, _chairs_audio_session
    data          = request.json or {}
    config_id     = data.get('config_id', '')
    cfg_data, name = _chairs_config_data(config_id)
    # A caller with no song of its own (the physical remote has no song
    # picker at all -- it just presses START) should continue with whatever
    # song is actually active for this session, not silently jump back to
    # the config's static Admin default. Console/the operator's own dropdown
    # always sends an explicit song, so this fallback chain only matters for
    # a start with none. api_games_chairs_reset() clears chairs_state['song']
    # back to '', so a fresh reset still correctly falls through to the
    # config default rather than "remembering" a stale song forever.
    song = data.get('song') or chairs_state.get('song') or cfg_data.get('song', '')
    if not song:
        return jsonify({'ok': False, 'error': 'No song selected'}), 400
    fp = (ASSETS_DIR / 'music' / song).resolve()
    if not fp.is_relative_to((ASSETS_DIR / 'music').resolve()) or not fp.exists():
        return jsonify({'ok': False, 'error': 'Song file not found'}), 404

    is_first_round = chairs_state['round'] == 0
    # Only resume in place if it's the same song, mid-game, and nothing else has
    # touched the shared music channel (walkup, macro, console) since we paused it.
    resume = (not is_first_round
              and chairs_state.get('song') == song
              and _audio_session == _chairs_audio_session)

    with _chairs_lock:
        _chairs_stop_token += 1
        my_token = _chairs_stop_token
        chairs_state['round']       += 1
        chairs_state['playing']      = True
        chairs_state['config_id']    = config_id
        chairs_state['config_name']  = name
        chairs_state['song']         = song
        chairs_state['song_label']   = Path(song).stem

    if resume:
        pygame.mixer.music.unpause()
        audio_state['paused'] = False
        broadcast('audio_state', audio_state)
    else:
        # An operator-picked song (via the Console dropdown) needs its own trim,
        # not whatever offset was tuned for the config's original song — so an
        # explicit override always wins, even 0 (no trim), over the config default.
        offset_override = data.get('song_start_offset')
        start_pos = float(offset_override) if offset_override is not None else float(cfg_data.get('song_start_offset', 0) or 0)
        def _play():
            global _chairs_audio_session
            play_audio(str(fp), loops=-1, start_pos=start_pos, crossfade_ms=0)
            _chairs_audio_session = _audio_session
        threading.Thread(target=_play, daemon=True).start()

    broadcast('chairs_state', chairs_state)

    # Intro Game Entry / Screen fields fire once at GO LIVE (see /api/games/launch),
    # not here — the audience-facing screen shouldn't wait on the operator hitting START.

    scene_id = cfg_data.get('start_scene')
    if scene_id:
        threading.Thread(target=wled_set_scene, args=(scene_id,), daemon=True).start()

    if cfg_data.get('auto_stop', True):
        lo = float(cfg_data.get('min_interval', 15) or 15)
        hi = float(cfg_data.get('max_interval', 45) or 45)
        if hi < lo:
            lo, hi = hi, lo
        delay = random.uniform(lo, hi)
        def _auto_stop():
            time.sleep(delay)
            with _chairs_lock:
                if _chairs_stop_token != my_token:
                    return
            _chairs_do_stop(cfg_data)
        threading.Thread(target=_auto_stop, daemon=True).start()

    return jsonify({'ok': True, 'round': chairs_state['round']})

@app.route('/api/games/chairs/stop', methods=['POST'])
def api_games_chairs_stop():
    global _chairs_stop_token
    data      = request.json or {}
    config_id = data.get('config_id') or chairs_state.get('config_id')
    cfg_data, _ = _chairs_config_data(config_id)
    with _chairs_lock:
        _chairs_stop_token += 1  # cancels any pending auto-stop for this round
    _chairs_do_stop(cfg_data)
    return jsonify({'ok': True})

@app.route('/api/games/chairs/reset', methods=['POST'])
def api_games_chairs_reset():
    global chairs_state, _chairs_stop_token, _chairs_audio_session
    with _chairs_lock:
        _chairs_stop_token += 1
    stop_audio()
    _chairs_audio_session = -1
    chairs_state = {'round': 0, 'playing': False, 'config_id': '', 'config_name': '', 'song': '', 'song_label': ''}
    broadcast('chairs_state', chairs_state)
    return jsonify({'ok': True})

_wheel_fade_token = 0

@app.route('/api/games/wheel/audio/start', methods=['POST'])
def api_games_wheel_audio_start():
    wheel_dir = ASSETS_DIR / 'games' / 'wheel'
    fname = _wheel_find_file(wheel_dir, 'spin_music')
    if not fname:
        return jsonify({'ok': False, 'error': 'no spin music configured'})
    fpath = wheel_dir / fname
    threading.Thread(target=play_audio, args=(str(fpath),),
                     kwargs={'loops': -1, 'crossfade_ms': 0}, daemon=True).start()
    return jsonify({'ok': True})

@app.route('/api/games/wheel/audio/stop', methods=['POST'])
def api_games_wheel_audio_stop():
    global _wheel_fade_token, _sfx_channel
    _wheel_fade_token += 1
    my_token = _wheel_fade_token
    if _sfx_channel and _sfx_channel.get_busy():
        _sfx_channel.fadeout(1000)
    def _fade():
        if not pygame.mixer.music.get_busy():
            return
        orig  = pygame.mixer.music.get_volume()
        steps = 20
        for i in range(steps - 1, -1, -1):
            if _wheel_fade_token != my_token:
                return
            if not pygame.mixer.music.get_busy():
                break
            pygame.mixer.music.set_volume(orig * i / steps)
            time.sleep(1.0 / steps)
        if _wheel_fade_token == my_token:
            pygame.mixer.music.stop()
            pygame.mixer.music.set_volume(orig)
    threading.Thread(target=_fade, daemon=True).start()
    return jsonify({'ok': True})

def _schedule_wheel_ticks(n, spin_ms):
    """Play tick SFX server-side timed to match the wheel's easeOutQuartic physics."""
    if n < 2:
        return
    wheel_dir = ASSETS_DIR / 'games' / 'wheel'
    fname = _wheel_find_file(wheel_dir, 'spin_sfx')
    if not fname:
        return
    fpath = str(wheel_dir / fname)
    try:
        if fpath not in _sfx_cache:
            _sfx_cache[fpath] = pygame.mixer.Sound(fpath)
        sound = _sfx_cache[fpath]
        sound.set_volume(sfx_state['volume'] / 100)
    except Exception as e:
        log.error(f'wheel tick SFX load error: {e}')
        return

    # Approximate total delta: 5.5 full rotations (5 minimum + ~half rotation average)
    total_rotations = 5.5
    total_ticks = int(total_rotations * n)
    spin_dur_s = spin_ms / 1000.0

    def _run():
        start = time.time()
        for i in range(1, total_ticks + 1):
            pos = i / (total_rotations * n)
            if pos >= 1.0:
                break
            # Inverse of easeOutQuartic: t = 1 - (1-pos)^0.25
            t = 1.0 - (1.0 - pos) ** 0.25
            tick_time = t * spin_dur_s
            sleep_until = start + tick_time
            now = time.time()
            if sleep_until > now:
                time.sleep(sleep_until - now)
            try:
                sound.play()
            except Exception:
                pass

    threading.Thread(target=_run, daemon=True).start()

@app.route('/api/games/wheel/spin', methods=['POST'])
def api_games_wheel_spin():
    data = request.get_json(silent=True) or {}
    spin_ms = int(data.get('spin_duration', 6000))
    entries = data.get('entries', [])
    w = load_config().get('wheel', {})
    # Per-config scenes take priority over global wheel config
    spin_scene   = data.get('spin_scene')   or w.get('spin_scene',   '')
    winner_scene = data.get('winner_scene') or w.get('winner_scene', '')
    # Spin scene lighting
    if spin_scene:
        threading.Thread(target=wled_set_scene, args=(spin_scene,), daemon=True).start()
    # Start spin music
    wheel_dir = ASSETS_DIR / 'games' / 'wheel'
    fname = _wheel_find_file(wheel_dir, 'spin_music')
    if fname:
        fpath = wheel_dir / fname
        threading.Thread(target=play_audio, args=(str(fpath),),
                         kwargs={'loops': -1, 'crossfade_ms': 0}, daemon=True).start()
    # Tick SFX timed to wheel physics
    _schedule_wheel_ticks(len(entries), spin_ms)
    # After spin: stop music + winner lighting
    def _after_spin():
        time.sleep((spin_ms + 800) / 1000.0)
        requests.post('http://127.0.0.1/api/games/wheel/audio/stop')
        if winner_scene:
            wled_set_scene(winner_scene)
    threading.Thread(target=_after_spin, daemon=True).start()
    # Broadcast spin to display
    broadcast('wheel_spin', {
        'winner_index':  data.get('winner_index', 0),
        'entries':       data.get('entries', []),
        'entry_colors':  data.get('entry_colors', {}),
        'spin_duration': spin_ms,
    })
    return jsonify({'ok': True})

# ── AG TRIVIA ──
@app.route('/games/trivia')
def games_trivia():
    return send_from_directory(STATIC_DIR, 'games_trivia.html')

def _trivia_config_data(config_id):
    if not config_id:
        return {}, ''
    match = next((c for c in load_game_configs() if c['id'] == config_id), None)
    if not match:
        return {}, ''
    return (match.get('data') or {}), match.get('name', '')

_trivia_state = {}         # config_id -> {'index': int, 'revealed': bool, 'timer_end': float|None}
_trivia_state_lock = threading.Lock()

def _trivia_default_state():
    # started=False means "on the lobby screen" (game name + team scores if
    # linked, no question content yet) -- flips True once the operator taps
    # Start Game, same lobby-then-go pattern the Prize Wheel already has
    # (idle spin behind the walkup, then a real spin on the operator's cue).
    return {'index': 0, 'revealed': False, 'started': False, 'timer_end': None,
            'log': [], 'show_score': False, 'order': None}

def _trivia_real_index(st, question_count):
    """Map a state's play-order position to the actual index into questions[]."""
    order = st.get('order')
    if order and len(order) == question_count and 0 <= st['index'] < len(order):
        return order[st['index']]
    return st['index']

def _trivia_get_state(config_id, question_count):
    with _trivia_state_lock:
        st = _trivia_state.setdefault(config_id, _trivia_default_state())
        # Clamp defensively — a saved question list can shrink after a state already exists.
        if question_count:
            st['index'] = max(0, min(st['index'], question_count - 1))
        # A shuffle order that no longer matches the question count (list was
        # edited after this session's shuffle) can't be trusted — fall back
        # to sequential rather than risk an out-of-range/mismatched lookup.
        if st.get('order') and len(st['order']) != question_count:
            st['order'] = None
        return dict(st)

@app.route('/api/games/trivia/state')
def api_games_trivia_state():
    config_id = request.args.get('config_id', '')
    data, _   = _trivia_config_data(config_id)
    questions = data.get('questions', [])
    st = _trivia_get_state(config_id, len(questions))
    return jsonify({'index': st['index'], 'revealed': st['revealed'], 'started': st['started'],
                     'timer_end': st['timer_end'], 'log': st['log'], 'order': st['order'],
                     'show_score': st['show_score'], 'count': len(questions)})

@app.route('/api/games/trivia/start', methods=['POST'])
def api_games_trivia_start():
    """Operator-pressed START GAME — leaves the lobby screen (game name +
    team scores, shown since the walkup auto-revealed into it) and moves the
    display over to question 1. Also (re-)fires display_reveal_game so this
    still works as a plain reveal if the iframe somehow isn't up yet -- e.g.
    no intro entry was configured, or a dropped WS event -- harmless/idempotent
    if it's already showing."""
    body      = request.json or {}
    config_id = body.get('config_id', '')
    data, _   = _trivia_config_data(config_id)
    questions = data.get('questions', [])
    with _trivia_state_lock:
        st = _trivia_state.setdefault(config_id, _trivia_default_state())
        st['started'] = True
        new_state = dict(st)
    payload = {'config_id': config_id, 'index': new_state['index'], 'revealed': new_state['revealed'],
               'started': new_state['started'], 'timer_end': new_state['timer_end'],
               'log': new_state['log'], 'order': new_state['order'],
               'show_score': new_state['show_score'], 'count': len(questions)}
    broadcast('trivia_state', payload)
    disp_url = '/games/trivia?display=1' + (f'&config={config_id}' if config_id else '')
    if (_current_live_game.get('game_type_id') == 'trivia'
            and _current_live_game.get('config_id') == config_id):
        _current_live_game['revealed'] = True
    broadcast('display_reveal_game', {'url': disp_url})
    return jsonify({'ok': True, **payload})

@app.route('/api/games/trivia/action', methods=['POST'])
def api_games_trivia_action():
    body      = request.json or {}
    config_id = body.get('config_id', '')
    action    = body.get('action', '')
    data, _   = _trivia_config_data(config_id)
    questions = data.get('questions', [])

    if action in ('correct', 'incorrect'):
        scene = data.get('correct_scene' if action == 'correct' else 'incorrect_scene')
        sfx   = data.get('correct_sfx'   if action == 'correct' else 'incorrect_sfx')
        if scene:
            # Same flash-then-revert helper Head to Head uses for its own
            # correct/incorrect scenes — fires the scene, then reverts to
            # whatever was showing before, instead of leaving it stuck.
            # 1500ms, not H2H's 400ms default — 400 was too quick to register
            # as a deliberate cue rather than a flicker.
            _h2h_flash_and_revert(scene, 1500)
        if sfx:
            threading.Thread(target=_chairs_play_cue_file, args=(sfx,), daemon=True).start()
        # Log this mark against the current question — this is the session's
        # own running tally, independent of any linked Head to Head game (used
        # for standalone runs where there's no team scoreboard to keep score).
        with _trivia_state_lock:
            st = _trivia_state.setdefault(config_id, _trivia_default_state())
            real_idx = _trivia_real_index(st, len(questions))
            q = questions[real_idx] if questions and real_idx < len(questions) else None
            st['log'].append({'index': st['index'], 'question': (q or {}).get('question', ''),
                               'correct': action == 'correct'})
            new_state = dict(st)
        payload = {'config_id': config_id, 'index': new_state['index'], 'revealed': new_state['revealed'],
                   'started': new_state['started'], 'timer_end': new_state['timer_end'],
                   'log': new_state['log'], 'order': new_state['order'],
                   'show_score': new_state['show_score'], 'count': len(questions)}
        broadcast('trivia_state', payload)
        return jsonify({'ok': True, **payload})

    with _trivia_state_lock:
        st = _trivia_state.setdefault(config_id, _trivia_default_state())
        if action == 'reveal':
            st['revealed']  = True
            st['timer_end'] = None   # guessing window is over once the answer shows
        elif action == 'next':
            if questions:
                st['index'] = min(st['index'] + 1, len(questions) - 1)
            st['revealed']   = False
            st['timer_end']  = None   # new question — timer must be started again if wanted
            st['show_score'] = False  # moving on implies going back to Q&A view
        elif action == 'prev':
            st['index'] = max(st['index'] - 1, 0)
            st['revealed']   = False
            st['timer_end']  = None
            st['show_score'] = False
        elif action == 'start_timer':
            secs = data.get('guess_timer_secs', 0) or 0
            if secs > 0:
                st['timer_end'] = time.time() + secs
        elif action == 'clear_timer':
            st['timer_end'] = None
        elif action == 'show_score':
            st['show_score'] = True
        elif action == 'hide_score':
            st['show_score'] = False
        elif action == 'clear_log':
            st['log'] = []
        elif action == 'toggle_log':
            # Operator fixes a mis-tap in the running log — flip that one
            # entry's correct/incorrect instead of having to clear and redo
            # the whole tally.
            li = body.get('log_index')
            if isinstance(li, int) and 0 <= li < len(st['log']):
                st['log'][li]['correct'] = not st['log'][li]['correct']
        new_state = dict(st)

    payload = {'config_id': config_id, 'index': new_state['index'], 'revealed': new_state['revealed'],
               'started': new_state['started'], 'timer_end': new_state['timer_end'],
               'log': new_state['log'], 'order': new_state['order'],
               'show_score': new_state['show_score'], 'count': len(questions)}
    broadcast('trivia_state', payload)
    return jsonify({'ok': True, **payload})

@app.route('/api/games/trivia/import', methods=['POST'])
def api_games_trivia_import():
    """Parse an uploaded CSV or .xlsx question bank. Returns rows only — the
    client merges them into the config's own questions list and saves through
    the normal /api/game_configs PUT, so there's a single save path."""
    if 'file' not in request.files:
        return jsonify({'ok': False, 'error': 'No file'}), 400
    f    = request.files['file']
    name = (f.filename or '').lower()
    rows = []
    try:
        if name.endswith('.xlsx'):
            if not _HAS_OPENPYXL:
                return jsonify({'ok': False, 'error': 'openpyxl not installed on the Pi — run: pip install openpyxl'}), 500
            wb = _openpyxl.load_workbook(f.stream, read_only=True, data_only=True)
            ws = wb.active
            for row in ws.iter_rows(values_only=True):
                if row and any(c is not None for c in row):
                    rows.append([('' if c is None else str(c)) for c in row])
        else:
            text = f.read().decode('utf-8-sig', errors='replace')
            for row in csv.reader(io.StringIO(text)):
                if row and any(c.strip() for c in row):
                    rows.append(row)
    except Exception as e:
        return jsonify({'ok': False, 'error': f'Could not parse file: {e}'}), 400

    if not rows:
        return jsonify({'ok': True, 'questions': []})

    # First row is a header if it doesn't look like actual Q/A content — match
    # question/answer/category case-insensitively; otherwise assume columns
    # 1/2/3 = question/answer/category and treat row 1 as data, not a header.
    header = [c.strip().lower() for c in rows[0]]
    col_map = {}
    for i, h in enumerate(header):
        if h in ('question', 'q'):
            col_map['question'] = i
        elif h in ('answer', 'a'):
            col_map['answer'] = i
        elif h in ('category', 'cat'):
            col_map['category'] = i
    data_rows = rows[1:] if col_map else rows
    if not col_map:
        col_map = {'question': 0, 'answer': 1, 'category': 2}

    questions = []
    for row in data_rows:
        def _cell(key):
            i = col_map.get(key)
            return row[i].strip() if i is not None and i < len(row) and row[i] else ''
        q, a = _cell('question'), _cell('answer')
        if not q and not a:
            continue
        questions.append({'id': f'q_{uuid.uuid4().hex[:10]}', 'question': q, 'answer': a, 'category': _cell('category')})

    return jsonify({'ok': True, 'questions': questions})

