@app.route('/api/lights/brightness')
def api_lights_brightness():
    global _master_dim
    v = int(request.args.get('v', 75))
    _master_dim = v / 100.0
    bri = int(v * 2.55)
    wled_targets = (
        [d for d in config.get('wled_devices', []) if not d.get('independent')] +
        [{'id': n['id'], 'ip': n['ip']} for n in config.get('pole_nodes', []) if n.get('ip')]
    )
    def _apply():
        for t in wled_targets:
            try:
                requests.post(f"http://{_resolve_ip_once(t['ip'])}/json/state",
                              json={'bri': bri}, timeout=0.5)
            except Exception as e:
                _invalidate_ip(t['ip'])
                log.warning(f"Brightness {t['id']}: {e}")
        # Re-apply last scene DMX with new scale (skip if animation is driving DMX)
        if _last_scene_dmx and not _dmx_anim_active:
            nodes_map = {n['id']: n for n in config.get('pole_nodes', []) if n.get('ip')}
            for node_id, fixtures in _last_scene_dmx.items():
                node = nodes_map.get(node_id)
                if not node:
                    continue
                scaled = [{'start': f['start'],
                           'channels': _dim_channels(f['channels'], _master_dim, f.get('dim_mask'))}
                          for f in fixtures]
                try:
                    requests.post(f"http://{_resolve_ip_once(node['ip'])}/dmx",
                                  json={'fixtures': scaled}, timeout=0.5)
                except Exception as e:
                    _invalidate_ip(node['ip'])
                    log.warning(f"DMX dim {node_id}: {e}")
    threading.Thread(target=_apply, daemon=True).start()
    return jsonify({'ok': True, 'brightness': v})


def _wled_ip_for_device(device_id):
    """Returns a resolved literal IP (not the raw mDNS hostname) — every
    caller of this helper gets cache-backed resolution for free."""
    cfg = load_config()
    for d in cfg.get('wled_devices', []):
        if d['id'] == device_id and d.get('ip'):
            return _resolve_ip_once(d['ip'])
    for n in cfg.get('pole_nodes', []):
        if n['id'] == device_id and n.get('ip'):
            return _resolve_ip_once(n['ip'])
    return None


@app.route('/api/wled/tune', methods=['POST'])
def api_wled_tune():
    data      = request.get_json() or {}
    device_id = data.get('device_id', '')
    params    = {k: v for k, v in data.items()
                 if k in ('sx', 'ix', 'c1', 'c2', 'c3') and v is not None}
    ip = _wled_ip_for_device(device_id)
    if not ip:
        return jsonify({'ok': False, 'error': 'device not found'}), 404
    try:
        state = requests.get(f'http://{ip}/json/state', timeout=1.0).json()
        segs  = state.get('seg', [{'id': 0}])
        updated = [dict({'id': s.get('id', i)}, **params) for i, s in enumerate(segs)]
        requests.post(f'http://{ip}/json', json={'seg': updated}, timeout=1.0)
        return jsonify({'ok': True})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 502


@app.route('/api/wled/state/<device_id>')
def api_wled_device_state(device_id):
    ip = _wled_ip_for_device(device_id)
    if not ip:
        return jsonify({'ok': False, 'error': 'device not found'}), 404
    try:
        state = requests.get(f'http://{ip}/json/state', timeout=1.0).json()
        seg0  = state.get('seg', [{}])[0]
        return jsonify({'ok': True, 'sx': seg0.get('sx', 128), 'ix': seg0.get('ix', 128),
                        'c1': seg0.get('c1', 128), 'c2': seg0.get('c2', 128),
                        'c3': seg0.get('c3', 128)})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 502


# ── POLE NODES ──
DHCP_NODES_CONF = '/etc/dnsmasq.d/musicman-nodes.conf'

def _arp_table():
    """Read /proc/net/arp → {ip: mac} for complete entries only."""
    table = {}
    try:
        with open('/proc/net/arp') as f:
            for line in f.readlines()[1:]:
                parts = line.split()
                if len(parts) >= 4 and parts[2] == '0x2':
                    table[parts[0]] = parts[3]
    except Exception:
        pass
    return table

def _id_to_slug(nid):
    return re.sub(r'[^a-z0-9-]+', '-', nid.lower()).strip('-')

def _sync_dhcp_reservations():
    """Write /etc/dnsmasq.d/musicman-nodes.conf and reload dnsmasq.
    Requires sudoers: pi ALL=(ALL) NOPASSWD: /usr/bin/tee /etc/dnsmasq.d/musicman-nodes.conf
                      pi ALL=(ALL) NOPASSWD: /bin/systemctl reload dnsmasq
    Returns {'ok': bool, 'reserved': int, 'pending': int, 'error': str|None}
    """
    cfg = load_config()
    arp = _arp_table()

    lines = ['# Auto-generated by MusicMan — do not edit manually\n']
    reserved = 0
    pending = []

    for node in cfg.get('pole_nodes', []):
        ip   = (node.get('ip')   or '').strip()
        nid  = (node.get('id')   or '').strip()
        name = (node.get('name') or nid).strip()
        if not ip or not nid:
            continue
        mac  = arp.get(ip)
        slug = _id_to_slug(name or nid)
        if mac:
            lines.append(f'dhcp-host={mac},{slug},{ip}\n')
            reserved += 1
        else:
            pending.append(f'{name} ({ip})')
            lines.append(f'# {name}: not in ARP cache — connect device first\n')

    for dev in cfg.get('wled_devices', []):
        ip   = (dev.get('ip')   or '').strip()
        did  = (dev.get('id')   or '').strip()
        name = (dev.get('name') or did).strip()
        if not ip or not did:
            continue
        mac  = arp.get(ip)
        slug = _id_to_slug(name or did)
        if mac:
            lines.append(f'dhcp-host={mac},{slug},{ip}\n')
            reserved += 1
        else:
            pending.append(f'{name} ({ip})')
            lines.append(f'# {name}: not in ARP cache — connect device first\n')

    content = ''.join(lines)
    try:
        r = subprocess.run(
            ['sudo', '-n', 'tee', DHCP_NODES_CONF],
            input=content.encode(), capture_output=True, timeout=5
        )
        if r.returncode != 0:
            return {'ok': False, 'reserved': 0, 'pending': pending,
                    'error': r.stderr.decode().strip() or 'tee failed'}
        subprocess.run(['sudo', '-n', 'systemctl', 'reload', 'dnsmasq'],
                       capture_output=True, timeout=5)
        return {'ok': True, 'reserved': reserved, 'pending': pending, 'error': None}
    except Exception as e:
        return {'ok': False, 'reserved': 0, 'pending': pending, 'error': str(e)}

@app.route('/api/admin/sync_dhcp', methods=['POST'])
def api_sync_dhcp():
    return jsonify(_sync_dhcp_reservations())

