@app.route('/api/macro/run')
def api_macro_run():
    name   = request.args.get('name', '')
    cfg    = config
    macros = {m['id']: m for m in cfg.get('macros', [])}
    if name not in macros:
        log.warning(f"Macro not found: {name}")
        return jsonify({'ok': False, 'error': f'Macro not found: {name}'}), 404
    # Check if this macro is part of the show flow and broadcast which step fired
    macro_obj = macros[name]
    step_name  = macro_obj.get('name', name)
    step_color = '#F5A623'
    matched_idx = None
    matched_desc = ''
    for idx, entry in enumerate(cfg.get('show_flow', [])):
        if entry.get('macro_id') == name:
            step_name  = entry.get('name') or step_name
            step_color = entry.get('color', step_color)
            matched_idx = idx
            matched_desc = entry.get('desc', '')
            broadcast('show_step', {'index': idx, 'macro_id': name, 'name': step_name, 'desc': matched_desc})
            break
    _set_current_show_step(index=matched_idx, type='macro', name=step_name, desc=matched_desc)
    # Always update projector display when a macro fires
    disp = {'name': step_name, 'color': step_color}
    img  = macro_obj.get('display_image', '')
    if img:
        disp['image'] = f'/assets/macros/{name}/{img}'
    _ensure_display_for('display_step', disp)
    global _macro_cancel
    _macro_cancel.set()
    _macro_cancel = threading.Event()
    # matched_idx lets any walkup_circle/walkup_role step inside this macro chain a
    # next_preload the same way show-flow-advanced walkups do (see fire_walkup) —
    # without it, a macro fired directly (the normal case for every macro button:
    # Console, Admin TEST, StreamDeck) never warms whatever plays next, guaranteeing
    # a cold start regardless of how that next thing gets fired.
    threading.Thread(target=execute_macro, args=(macro_obj, _macro_cancel, matched_idx), daemon=True).start()
    return jsonify({'ok': True})

def _walkup_preload_payload_for_item(item_type, target_id, cfg):
    """Return a walkup_preload payload dict for a circle, role, or game entry, or None if not found."""
    item_key = {'circle': 'circles', 'role': 'roles', 'game_entry': 'game_entries'}.get(item_type, 'circles')
    items    = {i['id']: i for i in cfg.get(item_key, [])}
    item     = items.get(target_id)
    if not item:
        return None
    assets   = item.get('assets', {})
    base_dir = ASSETS_DIR / item_key
    return {
        'type':            item_type,
        'id':              target_id,
        'animation_intro': _versioned_walkup_file(base_dir, target_id, assets.get('animation_intro', '')),
        'animation':       _versioned_walkup_file(base_dir, target_id, assets.get('animation', '')),
    }

def _get_next_walkup_preload(cfg, idx):
    """Return walkup_preload payload for the first walkup (or game intro) after
    show_flow[idx]. Game steps preload their own Intro Game Entry video the same
    way circle/role walkups do — a Prize Wheel or Musical Chairs step scheduled
    next in the flow gets its intro warmed while the current step is still
    playing, instead of cold-starting the moment it's reached."""
    if idx is None:
        return None
    flow = cfg.get('show_flow', [])
    if idx + 1 >= len(flow):
        return None
    nxt      = flow[idx + 1]
    nxt_type = nxt.get('type', 'macro')
    if nxt_type == 'circle':
        return _walkup_preload_payload_for_item('circle', nxt.get('target_id', ''), cfg)
    elif nxt_type == 'role':
        return _walkup_preload_payload_for_item('role', nxt.get('target_id', ''), cfg)
    elif nxt_type == 'game':
        intro_entry = _intro_entry_for_game(nxt.get('game_type_id', ''), nxt.get('game_config_id', ''))
        if intro_entry:
            payload = _walkup_preload_payload_for_item('game_entry', intro_entry, cfg)
            if payload:
                return payload
        return _get_next_walkup_preload(cfg, idx + 1)
    elif nxt_type == 'macro':
        macro_id  = nxt.get('macro_id', '')
        macros    = {m['id']: m for m in cfg.get('macros', [])}
        macro_obj = macros.get(macro_id)
        if macro_obj:
            for step in macro_obj.get('steps', []):
                if step.get('action') == 'walkup_circle':
                    return _walkup_preload_payload_for_item('circle', step.get('circle_id', ''), cfg)
                elif step.get('action') == 'walkup_role':
                    return _walkup_preload_payload_for_item('role', step.get('role_id', ''), cfg)
                elif step.get('action') == 'game':
                    intro_entry = _intro_entry_for_game(step.get('game_type_id', ''), step.get('game_config_id', ''))
                    if intro_entry:
                        payload = _walkup_preload_payload_for_item('game_entry', intro_entry, cfg)
                        if payload:
                            return payload
    elif nxt_type == 'vs_card':
        # Skip non-walkup steps and preload for whatever follows
        return _get_next_walkup_preload(cfg, idx + 1)
    return None


@app.route('/api/show/fire')
def api_show_fire():
    """Fire a show-flow step by index. Delegates to macro/run logic."""
    try:
        idx = int(request.args.get('index', -1))
    except (TypeError, ValueError):
        return jsonify({'ok': False, 'error': 'invalid index'}), 400
    cfg  = config
    flow = cfg.get('show_flow', [])
    if idx < 0 or idx >= len(flow):
        return jsonify({'ok': False, 'error': 'index out of range'}), 404

    entry     = flow[idx]
    step_type = entry.get('type', 'macro')
    step_desc = entry.get('desc', '')
    # Cancel whatever's currently running (a looping macro especially) before firing
    # this step — a walkup/game/vs_card advance used to leave a looping macro like
    # Announcements Loop completely unaware anything else had fired, so its next
    # step would broadcast straight over the walkup that just started playing.
    global _macro_cancel
    _macro_cancel.set()
    _macro_cancel = threading.Event()
    if step_type == 'circle':
        target_id = entry.get('target_id', '')
        step_name = entry.get('name', target_id)
        _set_current_show_step(index=idx, type='circle', name=step_name, desc=step_desc)
        broadcast('show_step', {'index': idx, 'name': step_name, 'desc': step_desc})
        _navigate_home_if_needed()
        threading.Thread(target=fire_walkup, kwargs={'circle_id': target_id, 'show_flow_idx': idx}, daemon=True).start()
    elif step_type == 'role':
        target_id = entry.get('target_id', '')
        step_name = entry.get('name', target_id)
        _set_current_show_step(index=idx, type='role', name=step_name, desc=step_desc)
        broadcast('show_step', {'index': idx, 'name': step_name, 'desc': step_desc})
        _navigate_home_if_needed()
        threading.Thread(target=fire_walkup, kwargs={'role_id': target_id, 'show_flow_idx': idx}, daemon=True).start()
    elif step_type == 'game':
        game_type_id   = entry.get('game_type_id', '')
        game_config_id = entry.get('game_config_id', '')
        gt             = GAME_TYPES.get(game_type_id, {})
        step_name      = entry.get('name') or gt.get('label', 'Game')
        ctrl_url, disp_url = _launch_game(game_type_id, game_config_id)
        _set_current_show_step(index=idx, type='game', name=step_name, desc=step_desc,
                                game_type_id=game_type_id, game_config_id=game_config_id,
                                controller_url=ctrl_url, display_url=disp_url)
        broadcast('show_step', {'index': idx, 'name': step_name, 'desc': step_desc, 'type': 'game'})
        broadcast('launch_game', {
            'game_type_id':   game_type_id,
            'game_config_id': game_config_id,
            'controller_url': ctrl_url,
            'display_url':    disp_url,
            'name':           step_name,
        })
    elif step_type == 'vs_card':
        card_id   = entry.get('vs_card_id', '')
        cards     = {c['id']: c for c in load_vs_cards()}
        card      = dict(cards.get(card_id, {}))
        step_name = entry.get('name') or card.get('name', 'VS')
        _set_current_show_step(index=idx, type='vs_card', name=step_name, desc=step_desc)
        broadcast('show_step', {'index': idx, 'name': step_name, 'desc': step_desc, 'type': 'vs_card'})
        if card:
            card = _vs_card_resolve_images(card, card_id)
            _ensure_display_for('display_vs_card', card)
        else:
            log.warning(f'show/fire: vs_card not found: {card_id!r}')
    else:
        macro_id  = entry.get('macro_id', '')
        macros    = {m['id']: m for m in cfg.get('macros', [])}
        macro_obj = macros.get(macro_id)
        if not macro_obj:
            log.warning(f'show/fire: macro not found: {macro_id!r}')
            return jsonify({'ok': False, 'error': f'macro not found: {macro_id}'}), 404
        step_name  = entry.get('name') or macro_obj.get('name', macro_id)
        step_color = entry.get('color', '#F5A623')
        # Navigation only, not an auto-start -- the macro's own timer_start/
        # setup_skit_timer step (if present) is what actually starts it, same
        # as it always has. This just lets the remote follow along onto the
        # Timer screen automatically instead of the MC having to navigate
        # there by hand, the same way it already jumps into a live game.
        has_timer = any(s.get('action') in ('timer_start', 'setup_skit_timer') for s in macro_obj.get('steps', []))
        _set_current_show_step(index=idx, type='macro', name=step_name, desc=step_desc, has_timer=has_timer)
        broadcast('show_step', {'index': idx, 'macro_id': macro_id, 'name': step_name, 'desc': step_desc, 'has_timer': has_timer})
        disp = {'name': step_name, 'color': step_color}
        img  = macro_obj.get('display_image', '')
        if img:
            disp['image'] = f'/assets/macros/{macro_id}/{img}'
        _ensure_display_for('display_step', disp)
        threading.Thread(target=execute_macro, args=(macro_obj, _macro_cancel, idx), daemon=True).start()

    return jsonify({'ok': True})

@app.route('/api/show/reset')
def api_show_reset():
    _set_current_show_step()
    broadcast('show_step', {'index': None})
    return jsonify({'ok': True})

def _broadcast_display_only(item_type, item):
    """Show a circle/role's display without triggering audio or lighting."""
    assets   = item.get('assets', {})
    base_dir = ASSETS_DIR / ('circles' if item_type == 'circle' else 'roles')
    _ensure_display_for('display_walkup', {
        'id':        item.get('id', ''),
        'name':      item.get('name', ''),
        'color':     item.get('color', '#F5A623'),
        'type':      item_type,
        'animation': _versioned_walkup_file(base_dir, item.get('id', ''), assets.get('animation', '')),
        'logo':      assets.get('logo', ''),
    })

_VIDEO_EXTS_PY = {'.mp4', '.webm', '.mov', '.ogv'}

def _broadcast_timer_display(filename):
    global current_slide
    ext = Path(filename).suffix.lower()
    if ext in _VIDEO_EXTS_PY:
        current_slide = {}
        _ensure_display_for('display_animation', {'video': f'/assets/display/{filename}'})
    else:
        _ensure_display_for('display_step', {'image': f'/assets/display/{filename}'})

_AUDIO_ACTIONS = {'music', 'play_playlist', 'audio_stop', 'audio_fade', 'walkup_circle', 'walkup_role', 'walkup_game_entry'}

def execute_macro(macro, cancel=None, show_flow_idx=None):
    global config, current_slide, _viz_scene
    if cancel is None:
        cancel = threading.Event()
    log.info(f"Executing macro: {macro.get('id')}")
    steps = macro.get('steps', [])
    if not any(s.get('action') in _AUDIO_ACTIONS for s in steps):
        if pygame.mixer.music.get_busy():
            fade_audio(3)
    # Auto-hide any active viz when a new macro starts (the viz step will re-show if needed)
    if _viz_scene and not any(s.get('action') in ('viz', 'viz_hide') for s in steps):
        _viz_scene = None
        _stop_audio_analyzer()
        broadcast('viz_hide', {})
    # loop=True repeats the step list forever until cancelled — cancellation
    # is already checked promptly inside individual steps (wait/display_image
    # etc via cancel.wait()), so an infinite chain of steps is safe as long
    # as at least one such step exists per pass. Guard the empty-steps case
    # explicitly: chaining an infinite repeat of [] would spin forever with
    # nothing to ever observe the cancel flag.
    if macro.get('loop') and steps:
        step_iter = itertools.chain.from_iterable(itertools.repeat(steps))
    else:
        step_iter = iter(steps)

    for step in step_iter:
        action = step.get('action', '')
        try:
            if action == 'scene':
                wled_set_scene(step.get('scene', ''))
            elif action == 'sfx':
                sfx_name = step.get('name', '')
                sfx_dir  = ASSETS_DIR / 'sfx'
                for ext in ('.mp3', '.wav', '.ogg', '.flac'):
                    fp = sfx_dir / (sfx_name + ext)
                    if fp.exists():
                        play_sfx(str(fp))
                        break
                else:
                    log.warning(f"Macro SFX not found: {sfx_name}")
            elif action == 'audio_stop':
                kill_everything()
            elif action == 'audio_fade':
                fade_audio(step.get('duration', 3))
            elif action == 'timer_start':
                if not timer_state['running']:
                    # Delegate to the real start handler so expired reset + timer sound fire correctly
                    threading.Thread(target=api_timer_start, daemon=True).start()
            elif action == 'timer_reset':
                timer_state['running'] = False
                timer_state['seconds_remaining'] = config.get('timer', {}).get('duration', 180)
                timer_state['warning_fired'] = False
                timer_state['expired'] = False
                broadcast('timer_state', timer_state)
            elif action == 'setup_skit_timer':
                preset_name = step.get('preset', '')
                _cfg = dict(config)
                presets = _cfg.get('skit_timer_presets', {})
                preset = presets.get(preset_name)
                if preset:
                    t = _cfg.setdefault('timer', {})
                    t.update(preset)
                    t['active_preset'] = preset_name
                    save_config(_cfg)
                    config = _cfg
                    new_ts = _timer_state_from_cfg(_cfg)
                    was_running = timer_state['running']
                    secs_remaining = timer_state['seconds_remaining'] if was_running else new_ts['duration']
                    timer_state.update(new_ts)
                    timer_state['running'] = was_running
                    timer_state['seconds_remaining'] = secs_remaining
                    timer_state['preset_name'] = preset_name
                    broadcast('timer_state', timer_state)
                    broadcast('timer_preset_loaded', {'name': preset_name, 'duration': timer_state['duration']})
                    log.info(f"Skit timer configured from preset: {preset_name!r}")
                else:
                    log.warning(f"Skit timer preset not found: {preset_name!r}")
            elif action == 'music':
                fname = step.get('file', '')
                do_loop = -1 if step.get('loop') else 0
                music_dir = ASSETS_DIR / 'music'
                candidates = [music_dir / fname] + \
                    [music_dir / (fname + ext) for ext in ('.mp3', '.wav', '.ogg', '.flac', '.aac', '.m4a')]
                for fp in candidates:
                    if fp.exists():
                        threading.Thread(target=play_audio, args=(str(fp),), kwargs={'loops': do_loop}, daemon=True).start()
                        break
                else:
                    log.warning(f"Macro music not found: {fname}")
            elif action == 'play_playlist':
                path    = step.get('path', '')
                shuffle = bool(step.get('shuffle', False))
                if path:
                    if not Path(path).is_absolute():
                        mount = _find_usb_mount()
                        if mount:
                            path = str(Path(mount) / path)
                    play_playlist(path, shuffle=shuffle)
                else:
                    log.warning('play_playlist action: no path')
            elif action == 'walkup_circle':
                circle_id = step.get('circle_id', '')
                if circle_id:
                    _navigate_home_if_needed()  # non-blocking; fire_walkup crossfade gives display.html time to load
                    threading.Thread(target=fire_walkup, kwargs={'circle_id': circle_id, 'show_flow_idx': show_flow_idx}, daemon=True).start()
            elif action == 'walkup_role':
                role_id = step.get('role_id', '')
                if role_id:
                    _navigate_home_if_needed()
                    threading.Thread(target=fire_walkup, kwargs={'role_id': role_id, 'show_flow_idx': show_flow_idx}, daemon=True).start()
            elif action == 'walkup_game_entry':
                entry_id = step.get('game_entry_id', '')
                if entry_id:
                    _navigate_home_if_needed()
                    threading.Thread(target=fire_game_entry, kwargs={'entry_id': entry_id}, daemon=True).start()
            elif action == 'wait':
                if cancel.wait(timeout=float(step.get('seconds', 1))):
                    log.info(f"Macro {macro.get('id')} cancelled during wait")
                    return
            elif action == 'display_image':
                file = step.get('file', '')
                if file:
                    payload = {'image': f'/assets/display/{file}'}
                    _ensure_display_for('display_step', payload)
                dur = float(step.get('duration', 3))
                if dur > 0:
                    if cancel.wait(timeout=dur):
                        log.info(f"Macro {macro.get('id')} cancelled during display_image")
                        return
            elif action == 'display_anim':
                file = step.get('file', '')
                dur  = float(step.get('duration', 5))
                loop = bool(step.get('loop', False))
                hold = not loop and (dur == 0)
                if file:
                    current_slide = {}
                    payload = {'video': f'/assets/display/{file}', 'hold': hold, 'loop': loop,
                               'muted': bool(step.get('muted', True))}
                    _ensure_display_for('display_animation', payload)
                if dur > 0 and not loop:
                    if cancel.wait(timeout=dur):
                        log.info(f"Macro {macro.get('id')} cancelled during display_anim")
                        return
            elif action == 'display_circle':
                cid  = step.get('circle_id', '')
                _cfg = config
                item = next((c for c in _cfg.get('circles', []) if c['id'] == cid), None)
                if item:
                    _ensure_display_for('display_update', {'type': 'circle', 'item': item})
                    _broadcast_display_only('circle', item)
            elif action == 'display_role':
                rid  = step.get('role_id', '')
                _cfg = config
                item = next((r for r in _cfg.get('roles', []) if r['id'] == rid), None)
                if item:
                    _ensure_display_for('display_update', {'type': 'role', 'item': item})
                    _broadcast_display_only('role', item)
            elif action == 'slide':
                slide_data = {k: v for k, v in step.items() if k != 'action'}
                if slide_data.get('template') == 'qr' and slide_data.get('qr_url'):
                    slide_data['qr_data_url'] = _make_qr_data_url(slide_data['qr_url'])
                current_slide = slide_data
                _ensure_display_for('display_slide', slide_data)
            elif action == 'slide_clear':
                current_slide = {}
                _ensure_display_for('display_slide_clear', {})
            elif action == 'game':
                game_type_id   = step.get('game_type_id', '')
                game_config_id = step.get('game_config_id', '')
                gt             = GAME_TYPES.get(game_type_id, {})
                ctrl_url, disp_url = _launch_game(game_type_id, game_config_id)
                broadcast('launch_game', {
                    'game_type_id':   game_type_id,
                    'game_config_id': game_config_id,
                    'controller_url': ctrl_url,
                    'display_url':    disp_url,
                    'name':           gt.get('label', 'Game'),
                })
            elif action == 'shell_game':
                theme_id = step.get('theme_id', '')
                if theme_id:
                    _load_shell_game_theme(theme_id)  # loads its own hold too, but the step's own value below wins
                hold = step.get('hold', 5)
                url = f'/shell-game?hold={hold}'
                broadcast('display_navigate', {'url': url})
            elif action == 'saved_slide':
                sid  = step.get('slide_id', '')
                _cfg = config
                _sl  = next((s for s in _cfg.get('slides', []) if s['id'] == sid), None)
                if _sl:
                    slide_data = dict(_sl)
                    if slide_data.get('template') == 'qr' and slide_data.get('qr_url'):
                        slide_data['qr_data_url'] = _make_qr_data_url(slide_data['qr_url'])
                    current_slide = slide_data
                    _ensure_display_for('display_slide', slide_data)
            elif action == 'viz':
                preset_id = step.get('preset_id', '')
                preset    = None
                if preset_id:
                    preset = next((p for p in config.get('viz_presets', []) if p['id'] == preset_id), None)
                scene = (preset or {}).get('settings', {}).get('scene', step.get('scene', 'music'))
                if scene in ('music', 'crowd'):
                    _viz_scene = scene
                    payload = {'scene': scene}
                    if preset:
                        payload['settings'] = preset.get('settings', {})
                    broadcast('viz_show', payload)
                    if scene == 'music':
                        _start_audio_analyzer()
            elif action == 'viz_hide':
                _viz_scene = None
                _stop_audio_analyzer()
                broadcast('viz_hide', {})
            elif action == 'vs_card':
                card_id = step.get('vs_card_id', '')
                cards   = {c['id']: c for c in load_vs_cards()}
                card    = dict(cards.get(card_id, {}))
                if card:
                    _fire_vs_card_by_card(card, card_id)
                else:
                    log.warning(f"vs_card macro action: card not found: {card_id!r}")
            elif action == 'head_to_head':
                h2h_id = step.get('head_to_head_id', '')
                if not _show_head_to_head(h2h_id):
                    log.warning(f"head_to_head macro action: game not found: {h2h_id!r}")
            log.info(f"Macro step done: {action}")
        except Exception as e:
            log.error(f"Macro step error ({action}): {e}")

@app.route('/api/macro/walkup')
def api_walkup():
    circle = request.args.get('circle')
    role = request.args.get('role')
    _navigate_home_if_needed()
    # Cancel any currently-running macro (a looping one especially) — otherwise it
    # keeps firing its own steps over this walkup, unaware anything else started.
    global _macro_cancel
    _macro_cancel.set()
    _macro_cancel = threading.Event()
    threading.Thread(
        target=fire_walkup,
        kwargs={'circle_id': circle, 'role_id': role},
        daemon=True
    ).start()
    return jsonify({'ok': True})

